\section{Problem formulation on a bounded domain}\label{sect2}
%For $x\in\mathbb{R}^{2}$, given a sequence of 1-periodic obstacles $D$, whose inhomogeneity $\gamma(x)-1$ are compactly supported in each the periodic cells, whose center is denoted by . 
We first recall the definition of propagating values \cite{Kirsch1} (or the exceptional values in \cite{Kirsch2}).
\begin{definition}\label{def1}
Given a wavenumber $k>0$ and $\Lambda$-periodic refractive index $\gamma(x)$, we call $\alpha\in[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$ a \textbf{propagating value} if the following Helmholtz equation has a nonzero $\alpha$ quasi-periodic solution $u\in H^{1}_{\alpha,loc}(\mathbb{R}^{2})$,
\begin{equation*}
\Delta u + k^2 \gamma(x)u = 0. %\label{Hequ}
\end{equation*} 
which satisfies a Rayleigh propagation condition, namely, for some $H>h_0>0$, in $\Omega_{H}^{+}=\{x=(x_{1},x_{2})\in\Omega|x_{2}>H\}$
\begin{equation}
     u(x_{1},x_{2}) = \sum_{n\in \mathbb{Z}}u^{+}_{n}e^{i\alpha_{n}x_{1}+i\beta_{n}(x_{2}-H)}, \label{uRay}
\end{equation}
and in $\Omega_{H}^{-}=\{x=(x_{1},x_{2})\in\Omega|x_{2}<-H\}$
\begin{equation}
     u(x_{1},x_{2}) = \sum_{n\in \mathbb{Z}}u^{-}_{n}e^{i\alpha_{n}x_{1}-i\beta_{n}(x_{2}+H)}. \label{lRay}
\end{equation}
We call such $u$ the \textbf{propagating mode} corresponding to $\alpha$.
\end{definition}
\subsection{Variational problem with DtN operator}
The set of all propagating values is denoted by $P(k)$.
To tackle the problem in a bounded region, for any $u\in H^1_{\alpha,loc}(\mathbb{R}^2)$, since they have well-defined trace $u(x_{1},\pm H)\in H^{1/2}(\Gamma_{\pm H})$, which are also $\alpha$ quasi-periodic in the $x_{1}$ direction, we define the DtN operators $T^\pm_\alpha: H^{1/2}(\Gamma_{\pm H})\rightarrow H^{-1/2}(\Gamma_{\pm H})$ by
\begin{eqnarray*}
    T^+_\alpha u=\sum_{n\in\mathbb{Z}}i\beta_{n}u_{n}^{+}e^{i\alpha_{n}x_{1}}, x\mbox{ on }\Gamma_H 
\end{eqnarray*}
and 
\begin{eqnarray*}
    T^-_\alpha u=\sum_{n\in\mathbb{Z}}i\beta_{n}u_{n}^{-}e^{i\alpha_{n}x_{1}}, x\mbox{ on } \Gamma_{-H},
\end{eqnarray*}
with $u^{\pm}_{n},n\in\mathbb{Z}$ the well-defined Fourier modes corresponding to the well-defined trace $u(x_{1},\pm H)\in H^{1/2}(\Gamma_{\pm H})$. We denote $\Omega_H=\{(x_1,x_2)|-\frac{\Lambda}{2}<x_1<\frac{\Lambda}{2}, -H<x_2<H\}$. Let $H^1_\alpha(\Omega_H)=\{u|_{\Omega_H}| u\in H^1_{\alpha,loc}(\mathbb{R}^2)\}$ and $H^1_{per}(\Omega_H)=\{u\in H^1(\Omega_H)| u(-\Lambda/2,x_2)=u(\Lambda/2,x_2)\}$.
Then with the help of operators $T^{\pm}_\alpha$, 
we can formulate \eqref{Hequ}-\eqref{lRay} in $\Omega_{H}$ to the following weak problem: Find $\alpha$ and $0\neq u\in H^1_\alpha(\Omega_H)$, such that
\begin{equation}
\int_{\Omega_{H}}\nabla u \cdot\nabla \bar{v} - k^{2}\gamma(x)u\bar{v}dx -\int_{\Gamma_{H}}T_{\alpha}^{+}u\bar{v}ds-\int_{\Gamma_{-H}}T_{\alpha}^{-}u\bar{v}ds=0, \forall v \in H^1_\alpha(\Omega_H).\label{wk1}
\end{equation}
Since $u,v\in H^1_\alpha(\Omega_H)$, we can introduce $\phi,\psi \in H^1_{per}(\Omega_H)$ such that $u=\phi e^{i\alpha x_{1}},v=\psi e^{i\alpha x_{1}}$, let 
\begin{eqnarray*}
    a_{\alpha}(\phi,\psi)=\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} -2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi-(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx-\sum_{n\in\mathbb{Z}}i\beta_{n}\phi^{+}_{n}\bar{\psi}^{+}_{n}-\sum_{n\in\mathbb{Z}}i\beta_{n}\phi^{-}_{n}\bar{\psi}^{-}_{n}. 
\end{eqnarray*}
 Here, $\phi_{n}^{\pm},\psi_{n}^\pm,n\in\mathbb{Z}$ are the well-defined Fourier modes corresponding to the trace of $\phi,\psi$ on $\Gamma^{\pm}_{H}$. Thus, our problem of computing propagating values can be recast: Finding $\alpha\in[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$  and $0\neq \phi\in H^1_{per}(\Omega_H)$ such that
\begin{equation}
a_\alpha(\phi,\psi)=0, \forall \psi\in H^1_{per}(\Omega_H).\label{oripblm}
\end{equation}
Further, we may define an inner product on $H^{1}_{per}(\Omega_{H})$ by
\begin{equation}
(\phi,\psi)_{*}=\int_{\Omega_{H}}\nabla \phi\cdot \nabla \psi dx + \frac{2\pi}{\Lambda}\sum_{n\in\mathbb{Z}}\sqrt{1+n^{2}}(\phi_{n}^{+}\bar{\psi}^{+}_{n}+\phi^{-}_{n}\bar{\psi}^{-}_{n}).\label{starnorm}
\end{equation}
and we denote by $\|\cdot\|_*$, the norm induced by the inner product. In addition, let us consider the Banach space of all bounded linear operators $\mathcal{L}(H^1_{per}(\Omega_{H}),H^1_{per}(\Omega_{H}))$, with the operator norm 
induced by $||\cdot||_{*}$. Now we have

\begin{theorem}\label{Thm:1}
For any given $k>0$, and $\alpha\in [-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$, there is an isomorphism $T(\alpha)$ and a compact operator $K(\alpha)$ in $\mathcal{L}(H^1_{per}(\Omega_{H}),H^1_{per}(\Omega_{H}))$, such that for any $\phi,\psi\in H^{1}_{per}(\Omega_{H})$,
     \begin{equation*}
         a_{\alpha}(\phi,\psi)=(D(\alpha)\phi,\psi)_{*}=((T(\alpha)-K(\alpha))\phi,\psi)_{*}.
     \end{equation*}
     Where operator $D(\alpha)=T(\alpha)-K(\alpha)$.
 \end{theorem}
 \begin{proof}
 We may obtain that 
 \begin{eqnarray*}
a_{\alpha}(\phi,\psi)&=&\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} dx+\frac{2\pi}{\Lambda}\sum_{n\in\mathbb{Z}}\sqrt{n^2+1} (\phi_{n}^{+}\bar\psi_{n}^{+}+\phi_{n}^{-}\bar{\psi}_{n}^{-})\\
&-&\int_{\Omega_{H}}2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi+(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx\\
&-&\sum_{n\in\mathbb{Z}}(i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1} )\phi^{+}_{n}\bar{\psi}^{+}_{n}-\sum_{n\in\mathbb{Z}}(i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1} )\phi^{-}_{n}\bar{\psi}^{-}_{n}.
\end{eqnarray*}
Let
\begin{eqnarray}
&&a^1_\alpha(\phi,\psi)=\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi}dx +\frac{2\pi}{\Lambda}\sum_{n\in\mathbb{Z}}\sqrt{n^2+1}(\phi_{n}^{+}\bar\psi_{n}^{+}+\phi_{n}^{-}\bar\psi_{n}^{-}),\label{weaka1}\\
&&    a^2_{\alpha}(\phi,\psi)=\int_{\Omega_{H}}2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi+(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx,\label{weaka2}\\
&&a^3_\alpha(\phi,\psi)=\sum_{n\in\mathbb{Z}}(i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1})(\phi^{+}_{n}\bar{\psi}^{+}_{n}+\phi^{-}_{n}\bar{\psi}^{-}_{n}).\nonumber
\end{eqnarray}
Clearly,
$$a_\alpha(\phi,\psi)=a^1_\alpha(\phi,\psi)-a^2_\alpha(\phi,\psi)-a^3_{\alpha}(\phi,\psi).$$
For $a^1_{\alpha}(\phi,\psi)$ we have,
\begin{eqnarray*}
    |a_{\alpha}^1(\phi,\psi)|\leq||\phi||_{*}||\psi||_{*},
 ~a_{\alpha}^1(\phi,\phi)= ||\phi||^2_{*} ,
\end{eqnarray*}
 thus there is an isomorphism $T(\alpha)$ from $H^{1}_{per}(\Omega_{H})\rightarrow H^{1}_{per}(\Omega_{H})$, such that
\begin{equation*}
a^{1}_{\alpha}(\phi,\psi)=(T(\alpha)\phi,\psi)_*.
\end{equation*}
Next, using integration by parts, we have,  
$$a^2_{\alpha}(\phi,\psi)=\int_{\Omega_{H}}2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi+(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx=\int_{\Omega_{H}}-2i\alpha\frac{\partial \bar\psi}{\partial x_{1}}\phi+(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx.$$
By the compact embedding of $H^1_{per}(\Omega)\rightarrow L_{per}^2(\Omega_{H})$, we first obtain the embedding operator $E_{1}$, which is a compact operator, and consider $\hat{\phi}=E_{1}\phi$. Thus, for $\hat{\phi}$, we define the linear functional $L_{\hat{\phi}}(\psi)=a_{\alpha}^2(\phi,\psi)$. It is a bounded linear functional on $H^1_{per}(\Omega_{H})$, in terms of norm $||\cdot||_{*}$, thus, by the Riesz representation formula, there is a unique $\phi^{*}\in H^1_{per}(\Omega_{H})$, such that
\begin{equation*}
    L_{\hat{\phi}}(\psi)=(\phi^{*},\psi)_{*}, \forall \psi\in H^{1}_{per}(\Omega_{H}).
\end{equation*}
Then, we are led to define $E^{*}:L^2(\Omega_{H})\rightarrow H^{1}_{per}(\Omega_{H})$ given by $E^{*}(\hat{\phi})=\phi^{*}$. This is a bounded operator since
$a^{2}_{\alpha}(\phi,\psi)\leq C||\phi||_{L^2(\Omega_H)}||\psi||_{*}$. So we define $E(\alpha)=E^{*}E_1$, and it is a compact operator $H^1_{per}(\Omega_{H})\rightarrow H^{1}_{per}(\Omega_{H})$.

For $a^{3}_{\alpha}(\phi,\psi)$, we consider those $n\in U_{\alpha}$ since this index set is unbounded. There is a positive constant $C_1$ such that 
$|i\beta_{n}+\frac{2\pi}{\Lambda} \sqrt{n^2+1}|\leq C_1, \forall n\in U_\alpha$, since
\begin{equation*}
i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1}=-\sqrt{(\frac{2\pi}{\Lambda}n+\alpha)^2-k^2}+   \frac{2\pi}{\Lambda}\sqrt{n^2+1} =\frac{(\frac{2\pi}{\Lambda})^2+k^2-\alpha^2-\frac{4\pi\alpha}{\Lambda}n}{\sqrt{(\frac{2\pi}{\Lambda}n+\alpha)^2-k^2}+  \frac{2\pi}{\Lambda}\sqrt{n^2+1}}.
\end{equation*}
Taking $N_{0}:=\min\{|n||n\in U_{\alpha}\}$, we may consider, for $N>N_{0} $
\begin{eqnarray*}
  a^3_{\alpha,N}(\phi,\psi)=
    &-&\sum_{|n|<N}(i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1})(\phi^{+}_{n}\bar{\psi}^{+}_{n}+\phi^{-}_{n}\bar{\psi}^{-}_{n}).
\end{eqnarray*}
It is clear that
\begin{equation*}
    a^3_{\alpha,N}(\phi,\psi)\leq C ||\phi||_{*}||\psi||_{*}.
\end{equation*}
By Riesz representation theory, there is a finite rank operator $L_{N}(\alpha)\in\mathcal{L}(H^1_{per}(\Omega_{H}),H^1_{per}(\Omega_{H}))$, such that 
\begin{equation*}
     a^3_{\alpha,N}(\phi,\psi)=(L_{N}(\alpha)\phi,\psi)_{*}.
\end{equation*}
Since
\begin{eqnarray*}
    |a^3_{\alpha,N}(\phi,\psi)-a^3_{\alpha}(\phi,\psi)|&=&|\sum_{|n|\geq N}(i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1})(\phi^{+}_{n}\bar{\psi}^{+}_{n}+\phi^{-}_{n}\bar{\psi}^{-}_{n})|\\
    &=&\sum_{|n|\geq N}\frac{\Lambda|i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1}|}{2\pi\sqrt{1+n^2}}\frac{2\pi}{\Lambda}\sqrt{1+n^2}(\phi^{+}_{n}\bar{\psi}^{+}_{n}+\phi^{-}_{n}\bar{\psi}^{-}_{n})\\
    &\leq& \frac{C}{N}||\phi||_{*}||\psi||_{*}.
\end{eqnarray*}
It follows that there is a compact operator $L(\alpha)\in\mathcal{L}(H^1_{per}(\Omega_{H}),H^1_{per}(\Omega_{H}))$, such that
\begin{equation*}
a_{\alpha}^{3}(\phi,\psi)=(L(\alpha)\phi,\psi)_{*}.
\end{equation*} Finally, letting $K(\alpha)=E(\alpha)+L(\alpha)$, we obtain the compact operator as asserted.
 \end{proof}
%\section{Properties of the propagating values}\label{sect3}
\subsection{Properties of the propagating values}
To further study the properties of the propagating values, we extend $D(\alpha)$ to a neighborhood of $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$ in $\mathbb{C}$. Here, to ensure the well-behaved analytical property of the problem, often in articles of quasi-periodic scattering, the cut-off values \cite{Kirsch1} would be omitted to avoid pathological solutions to the linear equations. The cut-off values are defined by 
\begin{equation*}
\mathcal{A}(k)=\lbrace \alpha\in [-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]|k=|\alpha+\frac{2\pi}{\Lambda} m|,\textit{for some m}\in\mathbb{Z}\rbrace.
\end{equation*}
We follow the same path and adapt the following assumption.
\begin{assume}\label{keyasump}
The cut-off values are not propagating values, at $\hat{\alpha}\in A(k)$, $\dim Ker(D(\hat{\alpha}))$=0.
\end{assume}
Under this assumption, the following properties concerning the propagating values can be proved.
\begin{lemma}\label{finiteness}
    Under Assumption \ref{keyasump}, we have
 \begin{enumerate}
        \item There exists an open set $D\in\mathbb{C}$, with $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]\setminus \mathcal{A}(k)\subset D$ that consists of at most three connected components, such that the operator $D(\alpha)$ depends analytically and has finite dimension kernel on $\alpha\in D$.
        \item There exist at most finitely many propagating values of $D(\alpha)$ on $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$. Thus we denote by $P(k)$ the finite set of all propagating values on $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$. 
    \end{enumerate}
\end{lemma}
\begin{proof}
     1. For $\hat{\alpha}\in [-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]\setminus \mathcal{A}(k)$, denote by $B_{\hat{\alpha}}:=\{n\in\mathbb{Z}||\alpha_{n}|<k\}$. We take $\rho=\min_{n\in\mathbb{Z}}\{|\alpha_{n}-k|,|\alpha_{n}+k|\}$. Thus, we take $R(\hat{\alpha})=B_{\frac{1}{3}\rho}(\hat{\alpha})$, and for any $\alpha\in R(\hat{\alpha}),~\alpha=a_{1}+ia_{2}$, we extend the definition of $\beta_{n}$ by the branch cut along the negative imaginary axis of the square root. It follows that
 \begin{itemize}
         \item If $n\in B_{\hat{\alpha}}$, 
         \begin{equation*}
             \Re (k^2-(\alpha_{n})^2)=k^2-(\frac{2\pi}{\Lambda}n+a_{1})^2+a_{2}^2>\frac{4}{9}\rho^2>0.
         \end{equation*}
         \item If $n\notin B_{\hat{\alpha}}$
            \begin{equation*}
             \Re ((\alpha_{n})^2-k^2)=(\frac{2\pi}{\Lambda}n+a_{1})^2-k^2-a_{2}^2>\frac{1}{3}\rho^2>0.
         \end{equation*}
     \end{itemize}
     Thus, taking $D = \cup \{ R(\hat{\alpha}):\hat{\alpha}\in [-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]\setminus A(k)\}$. Since there are at most two cut-off points in $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$ for a given $k>0$, $D$ consists of at most three connected components. That the operator has a finite-dimensional kernel for all $\alpha\in D$ follows from exactly the same procedure as in the proof of Theorem 1. That ends the proof of the first part of the theorem.

     2. The proof follows the same procedure as \cite{Kirsch1}, which all require Theorem 5.1 of Chap 1 in \cite{Krein}. Assuming that there exist infinitely many propagating values of $D(\alpha)$ in $[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$, then at least one of the connected components includes an infinite number of propagating values. Without loss of generality, we take the infinite sequence in the component $D_{1}$. By Theorem 5.1 of Chap 1 in \cite{Krein}, the equation $D(\alpha)u=0$ has the same number of linearly independent solutions at every parameter $\alpha \in D_{1}$ except for finitely many, thus it has at least one solution for all $\alpha\in D_{1}$. Thus, at the boundary point of $D_{1}$, $D(\alpha)$ cannot be one-to-one, which contradicts Assumption 1.
\end{proof}
\begin{remark}
{The results in Lemma \ref{finiteness} have been proved in \cite{Kirsch2}, and here we adopt a different way to prove the results.  It is also known by \cite{Kirsch2} that the propagating values appear in pairs. That means, if $\alpha\in[-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$ is a propagating value, then $-\alpha$ is also a propagating value.}
\end{remark}
 By Lemma 2, we further have
\begin{corollary}\label{analyprop}
    Under Assumption 1, we have that for all $\alpha_{j}\in P(k),j\in\mathcal{J}$, there are $\delta_{j}>0$ such that the operator $D(\alpha)$ is analytical for $\alpha\in B_{\delta_{j}}(\alpha_{j})$ and has a finite-dimensional kernel. Furthermore, $D(\alpha)$ is one-to-one and continuous for $\alpha\in \overline{B_{\delta_{j}}(\alpha_{j})}\setminus \{\alpha_{j}\}$.
\end{corollary}
