\section{Truncation by perfectly matched layer}\label{sect3}

\subsection{The PML formulation}
Since the major nonlinearity in the calculation of propagating values due to the Rayleigh expansion
is reflected by the DtN operator, we consider the introduction of perfectly matched layer to truncate the unbounded domain and arrive at a polynomial eigenvalue problem. The perfectly matched layer technique, see \cite{ChenWu} for instance, under the case of quasi-periodic scattering is formally a complex coordinate stretching in the $x_{2}$-direction. Namely, along the $x_{2}$-direction, we introduce the absorbing PML layers in $\Omega_{H}^{\pm}$ of length $\delta$ respectively. The density of the PML is given by $s(x_{2})=s_{1}(x_{2})+is_{2}(x_{2})$, which satisfies that.
    \begin{equation*}
  s_{1},s_{2}\in C(\mathbb{R}),\quad s_{1}\geq 1,s_{2}\geq 0,\textit{ such that }s(x_{2})=1, -H\leq x_{2}\leq H .
    \end{equation*}
 Thus, the PML layers are given by 
    \begin{eqnarray*}
&        \Omega_{+}^{PML}=\lbrace(x_{1},x_{2}):-\frac{\Lambda}{2}<x_{1}<\frac{\Lambda}{2},\textit{ and }H\leq x_{2}\leq H+\delta\rbrace,\\
 &        \Omega_{-}^{PML}=\lbrace(x_{1},x_{2}):-\frac{\Lambda}{2}<x_{1}<\frac{\Lambda}{2},\textit{ and }-H-\delta\leq x_{2}\leq -H\rbrace,
    \end{eqnarray*}
 Now we may introduce a PML differential operator $\mathcal{L}$ via
\begin{equation*}
    \mathcal{L}:=\frac{\partial}{\partial x_{1}}s(x_{2})\frac{\partial}{\partial x_{1}}+\frac{\partial}{\partial x_{2}}\frac{1}{s(x_{2})}\frac{\partial}{\partial x_{2}}+s(x_{2})k^{2}\gamma(x).
\end{equation*}
    Let $\tilde{\Omega}_{H}=\Omega_{H}\cup\Omega^{PML}_{+}\cup\Omega^{PML}_{-}$, $\Gamma_1=\lbrace(x_{1},x_{2}):-\frac{\Lambda}{2}<x_{1}<\frac{\Lambda}{2}, x_{2}=H+\delta\rbrace$ and $\Gamma_2=\lbrace(x_{1},x_{2}):-\frac{\Lambda}{2}<x_{1}<\frac{\Lambda}{2}, x_{2}=-H-\delta\rbrace$, we may obtain the PML equation,
    \begin{equation}
        \mathcal{L}u=0,x\in \Omega.\label{PMLde}
    \end{equation}
    Further, we denote by $X(\tilde{\Omega}_{H})$ the following space of function
    \begin{equation*}
        X(\tilde{\Omega}_{H}):=\lbrace w \in H_{\alpha}^{1}(\tilde{\Omega}_{H})|w=0 \text{ on }\Gamma_{1}\cup \Gamma_{2} \rbrace.
    \end{equation*}
    Now the weak formulation for propagating values problem with PML truncation thus reads as follows: Finding $\alpha$ and $u\in X(\tilde{\Omega}_{H})$ such that for all $v\in X(\tilde{\Omega}_{H})$, 
    \begin{equation}
        a_{\tilde{\Omega}_{H}}(u,v)=\int_{\tilde{\Omega}_{H}}s(x_{2})\frac{\partial u}{\partial x_{1}} \cdot\frac{\partial \bar{v}}{\partial x_{1}}+\frac{1}{s(x_{2})}\frac{\partial u}{\partial x_{2}} \cdot\frac{\partial \bar{v}}{\partial x_{2}} - s(x_{2})k^{2}\gamma(x)u\bar{v}dx=0.\label{IMPplm}
    \end{equation}
 The propagating values are hidden in the functional space $X(\tilde\Omega_H)$ and cannot be easily computed. Next, we will introduce an explicit weak formulation for the propagating problem. Let $\phi\in X_{per}(\tilde{\Omega}_{H})$, where $X_{per}(\tilde{\Omega}_{H}):=\{w\in H^1_{per}(\tilde{\Omega}_{H})| w=0 \text{ on }\Gamma_1\cup\Gamma_2\}$, such that $u=\phi e^{i\alpha x_{1}}$, then $u\in X(\tilde\Omega_H)$. Substituting $u$ in the PML equation \eqref{PMLde}, we have the following
differential equation for $\phi$,
\begin{equation}
\frac{\partial}{\partial x_{1}}s(x_{2})\frac{\partial}{\partial x_{1}}\phi+\frac{\partial}{\partial x_{2}}\frac{1}{s(x_{2})}\frac{\partial}{\partial x_{2}}\phi+2i\alpha s(x_{2}) \frac{\partial \phi}{\partial x_{1}}+s(x_{2})(k^{2}\gamma-\alpha^2)\phi=0, \quad x \in \tilde{\Omega}_{H}.\label{phiPML0}
\end{equation}
Now, we introduce the following sesquilinear form
        \begin{eqnarray*}
        &&a_{\alpha,\tilde{\Omega}_{H}}(\phi,\psi)=\int_{\tilde{\Omega}_{H}}s(x_{2})\frac{\partial \phi}{\partial x_{1}} \cdot\frac{\partial \bar{\psi}}{\partial x_{1}} +\frac{1}{s(x_{2})}\frac{\partial \phi}{\partial x_{2}} \cdot\frac{\partial \bar{\psi}}{\partial x_{2}} \nonumber\\
        &&\qquad\qquad\qquad-2i\alpha s(x_{2})\frac{\partial \phi}{\partial x_{1}}\bar\psi-s(x_{2})
            (k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx,
        \text{ for }\phi,\psi\in X_{per}(\tilde\Omega_H).
        \end{eqnarray*}
% By simple calculation, we can find that $\int_{\tilde\Omega_H}s(x_2)\frac{\phi(x)}{\partial x_1}\bar\psi dx=-\int_{\tilde\Omega_H}s(x_2)\phi\frac{\partial\bar\psi}{\partial x_1}dx$ for $\phi,\psi\in X_{per}(\tilde\Omega_H)$.
 Then the corresponding propagating value problem reads: Finding $\alpha\in\mathbb{C}$, such that there is $\phi\in X_{per}(\tilde{\Omega}_{H})$, $\phi\neq 0$, which satisfies:
 \begin{equation}
     a_{\alpha,\tilde{\Omega}_{H}}(\phi,\psi)=0,\forall \psi\in X_{per}(\tilde{\Omega}_{H}).\label{Dpblm}
 \end{equation}
 It is just a quadratic eigenvalue problem. Thus the original non-polynomial eigenvalue problem has been truncated as a polynomial eigenvalue problem. We have to further investigate the perturbation of eigenvalue induced by the PML truncation. To this end, we consider the PML equation in region $\tilde{\Omega}_{H}\setminus\Omega_{H}$, since $\gamma(x)=1$, the equation \eqref{phiPML0} becomes
\begin{equation}
 \frac{\partial}{\partial x_{1}}s(x_{2})\frac{\partial}{\partial x_{1}}\phi+\frac{\partial}{\partial x_{2}}\frac{1}{s(x_{2})}\frac{\partial}{\partial x_{2}}\phi+2i\alpha s(x_{2}) \frac{\partial \phi}{\partial x_{1}}+s(x_{2})(k^{2}-\alpha^2)\phi=0, \quad x \in \tilde{\Omega}_{H}\setminus \Omega_{H}.\label{phiPML}
\end{equation}

Thus we denote by $\Omega_{PML}^{+}:=\{x\in \tilde{\Omega}_{H}\setminus\Omega_{H}|x_{2}>H\}$, $\Omega_{PML}^{-}:=\{x\in \tilde{\Omega}_{H}\setminus\Omega_{H}|x_{2}<-H\}$. Since $\phi$ is periodic in the $x_{1}$ direction, we consider its Fourier series expansion, $\phi(x_{1},x_{2})=\sum\phi_{n}(x_{2})e^{i\frac{2n\pi}{\Lambda}x_{1}}$, $\phi_n(x_2)=\frac{1}{\Lambda}\int^{\Lambda/2}_{-\Lambda/2}\phi(x_1,x_2)e^{i\frac{2n\pi}{\Lambda}x_{1}}dx_1$, inserting in \eqref{phiPML} gives
\begin{equation*}
    \sum_{n\in\mathbb{Z}}(\frac{\partial}{\partial x_{2}}\frac{1}{s(x_{2})}\frac{\partial}{\partial x_{2}}\phi_{n}(x_{2})+s(x_{2})(k-(\alpha+\frac{2\pi n}{\Lambda}))^2\phi_{n}(x_{2}))e^{i\frac{2n\pi}{\Lambda}x_{1}}=0,~x\in \Omega_{PML}^+\cup\Omega_{PML}^-.
\end{equation*}
 Thus $\phi(x_{1},x_{2})$ for $x\in \Omega_{PML}^{+}\cup \Omega_{PML}^{-}$ can be written as for some $A_{n}^\pm,B_{n}^\pm$, 
 \begin{eqnarray*}
\phi(x_{1},x_{2})=\left\{\begin{array}{ll}\sum_{n\in\mathbb{Z}}(A_{n}^{+}e^{i\beta_{n}\int_{x_{2}}^{\delta+ H}s(\tau)d\tau}+B_{n}^{+}e^{-i\beta_{n}\int_{x_{2}}^{\delta+ H}s(\tau)d\tau})e^{i\frac{2n\pi}{\Lambda}x_{1}}, &x\in\Omega_{PML}^{+},\\
\sum_{n\in\mathbb{Z}}(A_{n}^{-}e^{ i\beta_{n}\int^{x_{2}}_{-\delta-H}s(\tau)d\tau}+B_{n}^{-}e^{- i\beta_{n}\int^{x_{2}}_{-\delta- H}s(\tau)d\tau})e^{i\frac{2n\pi}{\Lambda}x_{1}}, &x\in \Omega_{PML}^{-}.
\end{array}\right.
\end{eqnarray*}
We also denote $\sigma_{+}=\int_{H}^{H+\delta}s(x_{2})dx_{2}$, $\sigma_{-}=\int_{-H-\delta}^{-H}s(x_{2})dx_{2}$, $|\sigma|=min\{|\sigma_{+}|,|\sigma_{-}|\}$. To determine $A_{n}^\pm,B_{n}^\pm$, we observe that $\phi$ has well defined Fourier modes $\phi^{\pm}_{n},n\in\mathbb{Z}$ corresponding to its well-defined trace on $\Gamma_{H}^{\pm}$.
Further, since that $\phi(x_{1},x_{2})=0,x_{2}=\pm\delta\pm H$, we obtain the following equations, namely, for $n\in\mathbb{Z}$
\begin{eqnarray*}
A_{n}^{\pm}e^{i\beta_{n}\sigma_{\pm}}+B_{n}^{\pm}e^{-i\beta_n\sigma_{\pm}}&=&\phi_{n}^{\pm},\\
A_{n}^{\pm}+B_{n}^{\pm}&=&0.
\end{eqnarray*}
It follows that
\begin{equation*}
    A_{n}^{\pm}=-B_{n}^{\pm}=\phi_{n}^{\pm}/(e^{i\beta_{n}\sigma_{\pm}}-e^{-i\beta_{n}\sigma_{\pm}}).
\end{equation*}
Thus
 \begin{eqnarray*}
\phi(x_{1},x_{2})=\left\{\begin{array}{ll}\sum_{n\in\mathbb{Z}}\frac{e^{i\beta_{n}\int_{x_{2}}^{\delta+ H}s(\tau)d\tau}-e^{-i\beta_{n}\int_{x_{2}}^{\delta+ H}s(\tau)d\tau}}{e^{i\beta_{n}\sigma_{+}}-e^{-i\beta_{n}\sigma_{+}}}\phi^{+}_{n}e^{i\frac{2n\pi}{\Lambda}x_{1}}, &x\in\Omega_{PML}^{+},\\
\sum_{n\in\mathbb{Z}}\frac{e^{ i\beta_{n}\int^{x_{2}}_{-\delta-H}s(\tau)d\tau}-e^{- i\beta_{n}\int^{x_{2}}_{-\delta-H}s(\tau)d\tau}}{e^{i\beta_{n}\sigma_{-}}-e^{-i\beta_{n}\sigma_{-}}}\phi_{n}^{-}e^{i\frac{2n\pi}{\Lambda}x_{1}}, &x\in \Omega_{PML}^{-}.
\end{array}\right.
\end{eqnarray*}
Now we consider the derivative $\frac{\partial \phi}{\partial x_{2}}$ on $\Gamma_{\pm H}$, and we may introduce the following  PML DtN mapping $T^{\pm}_{\alpha,PML}:X_{per}(\tilde{\Omega}_{H})\rightarrow H^{-\frac{1}{2}}(\Gamma_{\pm_{H}})$, notice that $\coth(\tau)=\frac{e^{\tau}+e^{-\tau}}{e^{\tau}-e^{-\tau}},\tau\in\mathbb{C}$, 
\begin{equation}
T^{\pm}_{\alpha,PML}\phi:=\frac{\partial \phi}{\partial n}|_{x_{2}=\pm H}=\sum_{n\in\mathbb{Z}}i\beta_{n}\coth(-i\beta_{n}\sigma^{\pm})\phi_{n}^{\pm}e^{i\frac{2\pi n}{\Lambda}x_{1}}. \label{dtPML} 
\end{equation}
Using Green's formula in $\tilde{\Omega}_{H}\setminus\Omega_{H}$, we obtain that, $\forall \alpha$ that is an eigenvalue of \eqref{Dpblm} with corresponding eigenvector $\phi$ and for all $\psi\in X_{per}(\tilde{\Omega}_{H})$,
\begin{eqnarray*}
&&a_{\alpha,\tilde{\Omega}_{H}}(\phi  ,\psi )=\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} -2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi-(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx\\
&&\qquad\qquad-\int_{\Gamma_{H}}T_{\alpha,PML}^{+}\phi\bar{\psi}ds-\int_{\Gamma_{-H}}T_{\alpha,PML}^{-}\phi\bar{\psi}ds.
\end{eqnarray*}
Thus we are led to define, for all $\phi,\psi\in H^{1}_{per}(\Omega_{H})$,
\begin{eqnarray*}
a_{\alpha,PML}(\phi ,\psi)=&\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} -2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi-(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx\\
&-\int_{\Gamma_{H}}T_{\alpha,PML}^{+}\phi\bar{\psi}ds-\int_{\Gamma_{-H}}T_{\alpha,PML}^{-}\phi\bar{\psi}ds.
\end{eqnarray*}
This gives the PML eigenvalue problem: Finding $\alpha$, such that there is $\phi\in H^1_{per}(\Omega_{H})$, $\phi\neq 0$, which satisfies:
\begin{equation}
     a_{\alpha,PML}(\phi,\psi)=0,\forall \psi\in H^1_{per}(\Omega_{H}).\label{PMLpblm}
 \end{equation}
And it follows that,
\begin{theorem}
    Let $\alpha$ be an eigenvalue of \eqref{PMLpblm}, with $\phi\in H^1_{per}(\Omega_{H})$ a corresponding eigenvector, there is $\hat{\phi}\in X_{per}(\tilde{\Omega}_{H})$ the corresponding eigenvector of $\alpha$ as an eigenvalue of \eqref{Dpblm}.
\end{theorem}
\begin{proof}
    $\forall \phi,\psi\in H^1_{per}(\Omega_{H})$, for $x_{2}>H$, we consider the following function
    \begin{equation*}
        \xi^{\pm}_{n}(x_{2})=e^{\pm i\beta_{n}\int_{x_{2}}^{\delta\pm H}s(\tau)d\tau}-e^{\mp i\beta_{n}\int_{x_{2}}^{\delta\pm H}s(\tau)d\tau}.
    \end{equation*}
    Thus we may define the following extension operator
    \begin{equation*}
       E^{\pm}(\alpha)\phi(x_{1},x_{2}) = \sum_{n\in\mathbb{Z}}\frac{\xi^{\pm}_{n}(x_{2})}{\xi^{\pm}_{n}(\pm H)}\phi_{n}^{\pm}e^{i\frac{2\pi}{\Lambda}nx_{1}}.
    \end{equation*}
    It follows that  $E^{\pm}(\alpha)\phi(x_{1},\pm H\pm \delta )=0$, and we may define $\hat{\phi}\in X_{per}(\tilde{\Omega}_{H})$ such that
 \begin{eqnarray*}
\hat{\phi}(x_{1},x_{2})=\left\{\begin{array}{ll} E^{\pm}(\alpha)\phi(x_{1},x_{2}), &|x_{2}|\in (H,H+\delta),\\
\phi(x_1,x_2), & \textit{ Otherwise }.
\end{array}\right.
\end{eqnarray*}
A direct computation verifies that $\hat{\phi}$ is an eigenvector of \eqref{Dpblm}.
\end{proof}

\subsection{Analysis of the PML DtN operator}%\label{sect5}
Recalling the PML DtN mapping given in \eqref{dtPML}, 
%\begin{equation}
%T^{\pm}_{\alpha,PML}\phi=\sum_{n\in\mathbb{Z}}i\beta_{n}\coth(-i\beta_{n}\sigma^{\pm})\phi_{n}^{\pm}e^{inx_{1}}. \label{dtPML} 
%\end{equation}
to discuss the perturbation of propagating values, we are led to investigate
\begin{equation*}
\coth(-i\beta_{j}\sigma^{\pm})-1=\frac{2}{\exp(-2i\beta_{j}\sigma^{\pm})-1}.
\end{equation*}
Now, for a general $\sigma\in\mathbb{C}$, We give special emphasis on the estimate of $h(z)$, which is defined by,
\begin{equation*}
    h(z):=\exp(-2i\sqrt{k^2-z^2}\sigma).
\end{equation*}
We use the branch cut along the negative imaginary axis for $\sqrt{z}$, $\sqrt{k^2-z^2}$.
In the following sections, we take a fixed $M>3$, and define
\begin{equation}\label{deltaPML}
\delta_{PML}=\min\lbrace\frac{\delta_{j}}{M}:j\in\mathcal{J}\rbrace.
\end{equation}

Further, given all $\alpha_{j}\in P(k)$, we introduce the critical region $\mathcal{V}$ and its periodic extension $\mathcal{V}_{inn}$
\begin{equation*}
\mathcal{V}=\cup_{j\in\mathcal{J}}B_{\delta_{PML}}(\alpha_{j}),\mathcal{V}_{inn}=\cup_{n\in\mathbb{Z}}(\mathcal{V}+\frac{2\pi n}{\Lambda}).
\end{equation*}
 Now we can prove the following lemma.
\begin{lemma}\label{lemma1}
    Under Assumption \ref{keyasump}, let $\sigma = |\sigma|e^{i\tau}$, 
 $\tau\in (\frac{\arctan(\frac{1}{M-1})}{2},\frac{\pi-\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2})$, there exits $\gamma>0$, independent of $|\sigma|$, $\delta_{PML}$, such that
    \begin{equation}
    |h(z)|\geq \exp(\gamma\sqrt{\delta_{PML}}|\sigma|\sqrt{|\Re(z)|+k}),\label{Exdec}
    \end{equation}
    for all $z\in \mathcal{V}_{inn}$.
\end{lemma}

\begin{proof}
   Letting $\sigma=|\sigma|e^{i\tau}$, $\sqrt{k^{2}-z^{2}}=r_{z}e^{i\theta}$. We note that the choice of the branch cut gives $\theta\in (-\frac{\pi}{4},\frac{3\pi}{4})$. It follows that,   
 \begin{equation}
   \Re (-2i\sqrt{k^2-z^2}\sigma)=2r_{z}|\sigma|sin(\theta+\tau).\label{exsin}
   \end{equation}
   It follows that, to prove the estimate \eqref{Exdec}, it suffices to prove the existence of $\gamma >0$ independent of $z\in \mathcal{V}_{inn}$ and an estimate on the lower bound of $r_{z}$ independent of $|\sigma|$. To start with, we denote $z = a+ ib$, and by the definition of $\delta_{PML}$, for all $z\in \mathcal{V}_{inn}$, $|b|<\delta_{PML}$, and trivially from the definition of $\delta_{PML}$, $M\delta_{PML}<k$. In addition, $|a|<k-(M-1)\delta_{PML}$ or $|a|>k+(M-1)\delta_{PML}$. 
%The following picture demonstrate these geometrical relations. 
%   \begin{figure}[ht]
%\centering
%\begin{tikzpicture}[scale=1,thick]
%\filldraw[fill = yellow] (-1, 0) circle [radius=0.4];
%\filldraw[fill = yellow] (0.75, 0) circle [radius=0.45];
%\draw[font = \Large] (0,0) node{$k$};
%\draw[font = \Large] (-1,0) node{$\alpha_{j}$};
%\draw[font = \Large] (0.75,0) node{$\alpha_{i}$};
%\draw (0,-1.5) -- (0,-1.45) node at(0,-1.8) {$0$};
%\end{tikzpicture}
%\caption{Demonstration of $\delta_{PML}$}
%\end{figure}
   We consider these two cases separately.
   \paragraph{Case(1)} $|a|<k-(M-1)\delta_{PML}$, 
   \begin{equation*}
   r_{z}^2=|k^{2}-z^{2}|=|k^{2}-a^2+b^2-2abi|\geq |k^{2}|-|a^2|\geq (|a|+k)(M-1)\delta_{PML}.
\end{equation*}    
   It also shows that $\Re (k^2-z^2)>0$, thus $\theta\in (-\frac{\pi}{4},\frac{\pi}{4})$. Now we consider 
   \begin{equation*}
       |\tan 2\theta|=|\frac{2ab}{k^2-a^2+b^2}|\leq |\frac{2a\delta_{PML}}{(|a|+k)(M-1)\delta_{PML}}|=\frac{2|a|}{(M-1)(|a|+k)}<\frac{1}{M-1},
   \end{equation*}
   thus, $ \theta\in (-\frac{\arctan(\frac{1}{M-1})}{2},\frac{\arctan{\frac{1}{M-1}}}{2})$, for given $\tau\in (\frac{\arctan{\frac{1}{M-1}}}{2},\pi-\frac{\arctan{\frac{1}{M-1}}}{2})$, let $\gamma_{1}=min(sin(\tau-\frac{\arctan{\frac{1}{M-1}}}{2}),sin(\tau+\frac{\arctan{\frac{1}{M-1}}}{2}))$, then $\sin(\theta+\tau)>\gamma_{1}>0$. 

\paragraph{Case(2)}$|a|>k+(M-1)\delta_{PML}$, we thus have
   \begin{eqnarray*}
    &&   |a|+k=|a|-k+2k>(3M-1)\delta_{PML},\\
    &&   r_{z}^2=|z^{2}-k^{2}|=|a^2-b^2+2abi-k^2|\geq |a^2-k^2-b^2|\\
    &&~~  \geq (|a|+k)(M-1)\delta_{PML}-\delta_{PML}^2
       \geq (|a|+k)((M-1)-1/(3M-1))\delta_{PML}
   \end{eqnarray*}
   and since $\Re (k^2-z^2)<0$, $\theta\in(\frac{\pi}{4},\frac{3\pi}{4})$. Furthermore, since
  \begin{eqnarray*}
       |\tan 2\theta|=|\frac{2ab}{k^2-a^2+b^2}|\leq |\frac{2a\delta_{PML}}{(|a|+k)((M-1)-1/(3M-1))\delta_{PML}}|\\
       =\frac{2(3M-1)|a|}{((3M-1)(M-1)-1)(|a|+k)}<\frac{2(3M-1)}{((3M-1)(M-1)-1)}.
   \end{eqnarray*}
   Thus
   \begin{equation*}
   \theta\in(\frac{\pi-\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2},\frac{\pi+\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2}).
   \end{equation*}
    As $|\tau|<\frac{\pi-\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2}$ is given, we take $\gamma_{2}=\min\{cos(\tau-\frac{\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2}),cos(\tau+\frac{\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2})\}$, then $\sin(\theta+\tau)>\gamma_{2}>0$.

    To sum up, taking $\tau\in (\frac{\arctan(\frac{1}{M-1})}{2},\frac{\pi-\arctan(\frac{2(3M-1)}{((3M-1)(M-1)-1)})}{2})$ and $\gamma=\min(\gamma_{1},\gamma_{2})$, we have the desired estimate \eqref{Exdec}.    
\end{proof}
\begin{remark}\label{tauassum}
We note that according to Lemma \ref{lemma1}, for large enough $M>0$, the region for valid $\tau$ expands to $(0,\frac{\pi}{2})$, so the technical assumption given by \cite{Zhang1} is not necessary for our analysis. We further remark that taking $\tau=\frac{\pi}{4}$ is sufficient; therefore, we automatically require that $\tau$ meets the requirement of Lemma \ref{lemma1} in the following sections.
\end{remark}
\begin{theorem}\label{expdecay}
Under Assumption \ref{keyasump},  for $|\sigma|$ large enough, there is an isomorphism $T(\alpha)$, and a compact operator $K_{\sigma}(\alpha)$ from $H^{1}_{per}(\Omega_{H})$ into themselves such that
 \begin{equation*}
         a_{\alpha,PML}(\phi,\psi)=(D_{\sigma}(\alpha)\phi,\psi)_{*}=((T(\alpha)-K_{\sigma}(\alpha))\phi,\psi)_{*}
     \end{equation*}
and
\begin{equation*}
    ||D(\alpha)-D_{\sigma}(\alpha)||_{*}\leq C e^{(-\gamma\sqrt{k\delta_{PML}}|\sigma|)}
\end{equation*}
for all $\alpha\in \mathcal{V}$. Where, $\gamma$ is defined in Lemma \ref{lemma1} and $D(\alpha)$ is defined in Theorem \ref{Thm:1}.
\end{theorem}
%% We include a proof here for reference
\begin{proof}
 Taking any $\alpha_{j}\in P(k)$, we consider $\alpha\in B_{\delta_{PML}}(\alpha_{j})$. Once again we have that
 \begin{eqnarray*}
a_{\alpha,PML}(\phi,\psi)&=&\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} dx+\frac{2\pi}{\Lambda}\sum_{n\in\mathbb{Z}}|\sqrt{n^2+1}(\phi_{n}^{+}\bar\psi_{n}^{+}+\phi_{n}^{-}\bar\psi_{n}^{-})\\
&-&\int_{\Omega_{H}}2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi dx- \int_{\Omega_{H}}(k^{2}\gamma(x)-\alpha^2)\phi\bar\psi dx\\
&-&\sum_{n\in\mathbb{Z}}(i\beta_{n}\coth(-i\beta_{n}\sigma^{+})+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{+}_{n}\bar{\psi}^{+}_{n}\\
&-&\sum_{n\in\mathbb{Z}}(i\beta_{n}\coth(-i\beta_{n}\sigma^{-})+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{-}_{n}\bar{\psi}^{-}_{n}.
\end{eqnarray*} 
Let $a_{\alpha,PML}(\phi,\psi)=a^1_{\alpha,PML}(\phi,\psi)-a^2_{\alpha,PML}(\phi,\psi)-a^3_{\alpha,PML}(\phi,\psi)$, where
\begin{eqnarray*}
&&a^1_{\alpha,PML}(\phi,\psi)=\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\psi} dx+\frac{2\pi}{\Lambda}\sum_{n\in\mathbb{Z}}\sqrt{n^2+1}(\phi_{n}^{+}\bar\psi_{n}^{+}+\phi_{n}^{-}\bar\psi_{n}^{-}),\\
&&a^2_{\alpha,PML}(\phi,\psi)=\int_{\Omega_{H}}2i\alpha\frac{\partial \phi}{\partial x_{1}}\bar\psi+(k^{2}\gamma(x)-\alpha^{2})\phi\bar{\psi}dx,\\
&&a^3_{\alpha,PML}(\phi,\psi)=\sum_{n\in\mathbb{Z}}(i\beta_{n}\coth(-i\beta_{n}\sigma^{+})+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{+}_{n}\bar{\psi}^{+}_{n}\\
&&\qquad\qquad+\sum_{n\in\mathbb{Z}}(i\beta_{n}\coth(-i\beta_{n}\sigma^{-})+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{-}_{n}\bar{\psi}^{-}_{n}.
\end{eqnarray*}
By the definitions \eqref{weaka1}-\eqref{weaka2}, we find that 
$$a^1_{\alpha,PML}(\phi,\psi)=a^1_{\alpha}(\phi,\psi), ~a^2_{\alpha,PML}(\phi,\psi)=a^2_{\alpha}(\phi,\psi).$$
%Then from the proof in theorem 1, there is an isomorphism $T(\alpha)$ and a compact operator $E(\alpha)$, from $H^{1}_{per}(\Omega_{H})\rightarrow H^{1}_{per}(\Omega_{H})$,such that
Then we have
\begin{equation*}
a^{1}_{\alpha,PML}(\phi,\psi)=(T(\alpha)\phi,\psi), \qquad a^{2}_{\alpha,PML}(\phi,\psi)=(E(\alpha)\phi,\psi),
\end{equation*}
where $T(\alpha), E(\alpha)$ are the same with the ones in the proof of Theorem \ref{Thm:1}.
For $a^{3}_{\alpha,PML}(\phi,\psi)$, note that, for $n\in U_{\alpha}$, since $\alpha_{n}\in \mathcal{V}_{inn}$, we use Lemma \ref{lemma1} to obtain that,
\begin{equation*}
|\beta_{n}(\coth(-i\beta_{n}\sigma^{\pm})-1)|\leq C|\beta_{n}|\exp(-\gamma\sqrt{\delta_{PML}}|\sigma|\sqrt{|(Re(\alpha_{n}))|+k}).
\end{equation*}
which is $o(\frac{1}{n})$ as $n\to\infty$. Thus, taking any $N>N_{0}$, where $N_{0}=\min\{|n||n\in U_{\alpha}\}$, 
\begin{eqnarray*}
    &&\sum_{n\in U_{\alpha},|n|>N}(i\beta_{n}\coth(-i\beta_{n}\sigma^{\pm})+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{\pm}_{n}\bar{\psi}^{\pm}_{n}\\
    &&~~=\sum_{n\in U_{\alpha},|n|>N}(i\beta_{n}\coth(-i\beta_{n}\sigma^{\pm})-i\beta_{n}+i\beta_{n}+\frac{2\pi}{\Lambda}\sqrt{n^2+1})\phi^{\pm}_{n}\bar{\psi}^{\pm}_{n}\\
    &&~~\leq \frac{C}{N} ||\phi||_{*}||\psi||_{*}.
\end{eqnarray*}
It follows from a similar argument as Theorem \ref{Thm:1} that there is a compact operator $L_{\sigma}(\alpha)$ such that
\begin{equation*}
a_{\alpha,PML}^{3}(\phi,\psi)=(L_{\sigma}(\alpha)\phi,\psi)_{*}.
\end{equation*} 
Then letting $K_\sigma(\alpha)=E(\alpha)+L_\sigma(\alpha)$, we obtain the compact operator as asserted. 
Finally, since 
\begin{eqnarray*}
    |(D_{\sigma}(\alpha)\phi,\psi)_{*}-(D(\alpha)\phi,\psi)_{*}|&\leq& |\sum_{n\in\mathbb{Z}}\beta_{n}(\coth(-i\beta_{n}\sigma^{\pm})-1)\phi^\pm_{n}\bar{\psi}^\pm_{n}|\\
    &\leq&C e^{-\gamma|\sigma|\sqrt{k\delta_{PML}}}|\sum_{n\in\mathbb{Z}}\beta_{n}\phi^\pm_{n}\bar{\psi}^\pm_{n}|\\
    &\leq&Ce^{-\gamma|\sigma|\sqrt{k\delta_{PML}}}||\phi||_{*}||\psi||_{*}.
\end{eqnarray*}
And the assertion follows by the definition of operator norm.
 \end{proof}
\section{Multiplicity of the propagating values} 
\label{sect4}
Since we are interested in the property of the propagating value inside the holomorphic region, let us introduce the concepts concerning the multiplicity of the propagating value $\alpha_{j}\in P(k)$ following \cite{Ammari}.
%%The quick look back on the multiplicity of the propagating value
Let $\mathcal{H}(\alpha_{j})$ be the set of all operator-valued functions $T(\alpha):H_{per}^{1}(\Omega_{H})\rightarrow H_{per}^{1}(\Omega_{H}),\forall \alpha\in B_{\delta_{j}}(\alpha_{j})$, which are holomorphic in $B_{\delta_{j}}(\alpha_{j})$, except possibly at $\alpha_{j}$. It follows that $D(\alpha)\in \mathcal{H}(\alpha_{j})$.
%% Thus it includes taking the inverse for some operator that has a zero at $\alpha_{j}$.
\begin{definition}
The point $\alpha_{j}$ is called an \textbf{eigenvalue} of $D(\alpha)\in \mathcal{H}(\alpha_{j})$, if there exists a vector-valued function $\phi(\alpha)\in H^{1}_{per}(\Omega_{H})$, such that
\begin{enumerate}
\item $\phi({\alpha})$ is holomorphic at $\alpha_{j}$, and $\phi(\alpha_{j})\neq 0$
\item $D(\alpha)\phi(\alpha)$ is holomorphic at $\alpha_{j}$ and vanishes at this point.
\end{enumerate} 
Here, $\phi(\alpha)$ is called a root function of $D(\alpha)$, associated with $\alpha_{j}$. The vector $\phi_{j}=\phi(\alpha_{j})$ is called an \textbf{eigenvector}. 
\end{definition}
Thus, every propagating value $\alpha_{j}\in \mathcal{P}(k)$ is an eigenvalue of $D(\alpha)$, and computing the propagating value $\alpha\in [-\frac{\pi}{\Lambda},\frac{\pi}{\Lambda}]$ is a non-polynomial nonlinear eigenvalue problem with respect to the linear operator $D(\alpha)$. The closure of the linear set of eigenvectors corresponding to $\alpha_{j}$ is denoted by $Ker(D(\alpha_{j}))$. Since $D(\alpha)$ has a finite-dimensional kernel for $\alpha_{j}\in B_{\delta_{j}}(\alpha_{j})$, $Ker(D(\alpha_{j}))$ is finite-dimensional. Now, taking an eigenvector $\phi_{j}\in Ker(D(\alpha_{j}))$, for every root function $\phi(\alpha)$, with $\phi(\alpha_{j})=\phi_{j}$, there exists a number $m(\phi)\geq 1$, and a function-valued function $\psi(\alpha)$ with values in $H^{1}_{per}(\Omega_{H})$, holomorphic at $\alpha_{j}$ such that
\begin{equation*}
D(\alpha)\phi(\alpha)=(\alpha-\alpha_{j})^{m(\phi)}\psi(\alpha),~\psi(\alpha_{j})\neq 0.
\end{equation*}
 We define the rank of $\phi_{j}$, denoted by $rank(\phi_{j})$, to be 
 \begin{equation*}
     rank(\phi_{j})=\max\{m(\phi)|\phi_{j}=\phi(\alpha_{j}),\phi(\alpha) \textit{ is a root function of }D(\alpha)\}.
 \end{equation*} 
 For the rest of this paper, we need the following assumption.
\begin{assume}\label{rankfinity}
      $\alpha_{j}\in\mathcal{P}(k)$, $\forall\phi\in Ker(D(\alpha_{j}))$, $rank(\phi)<\infty$.
  \end{assume}
Since $\alpha_{j}$ is isolated, $m(\phi)\leq dim(Ker(D(\alpha_{j})))$. We denote $n_{j}=dim(Ker(\alpha_{j}))$. A canonical system of eigenvectors $\phi_{j}^{m},m=1,\cdots,n_{j}$ of $Ker(D(\alpha_{j}))$ associated to $\alpha_{j}$, means that $rank(\phi_{j}^{m})$ is the largest in the direct complement in $Ker(D(\alpha_{j}))$ of the space spanned by $\phi_{j}^{n},n=1,\cdots,m-1$. Thus, we may define projection operators $P_{m}^{j},m=1\cdots,n_{j}$, which are one-dimensional projections onto spaces spanned by $\{\phi_{j}^{m}\}$. 
