\begin{definition}\cite{Ammari2010}\label{normalpoint}
Assume that $\alpha_{0}$ is a pole of $S(\alpha)$, and the Laurent series of $S(\alpha)$ at $\alpha_{0}$ has the following form:
    \begin{equation*}
        S(\alpha)=\sum_{j\geq -m}^{\infty}(\alpha-\alpha_{0})^{j}S_{j}.
    \end{equation*}
    If $S_{j}$,$j=-m, \cdots, -1$ satisfies that $dim R(S_{j})<\infty, j=-m, \cdots, -1$, we call $S(\alpha)$ finitely meromorphic at $\alpha_{0}$. If $S_{0}$ is a Fredholm operator, we say $S(\alpha)$ at $\alpha_{0}$ is of Fredholm type. If the Fredholm index of $S_{0}$ is 0, we say $S(\alpha)$ is of Fredholm type 0 at $\alpha_{0}$. If $S(\alpha)$is invertible and holomorphic at $\alpha_{0}$, we call $\alpha_{0}$ a regular point of $S(\alpha)$. If every point of $V\subset\mathbb{C}$ is a regular point of $S(\alpha)$,we call $S(\alpha)$ regular in $V$. If $S(\alpha)$is finitely meromorphic, of Fredholm type 0 at $\alpha_{0}$ and is regular in a punctured neighborhood of $\alpha_{0}$, we call $\alpha_{0}$ a normal point of $S(\alpha)$.
\end{definition}
Note that for $\alpha_{j}\in P(k)$, we have
\begin{theorem}\label{rieszno}
    Under Assumption \ref{keyasump}, the Riesz number of $D(\alpha_{j}),j\in P(k)$ is one, thus the Fredholm index of $D(\alpha_{j})$ is 0. 
\end{theorem}
\begin{proof}
    Let $\phi\in H^1_{per}(\Omega_{H})$ be a propagating mode corresponding to a fixed propagating value $\alpha_{j}\in P(k)$. Consider 
    \begin{equation*}
     a_{\alpha_{j}}(\phi,\phi)=\int_{\Omega_{H}}\nabla \phi \cdot\nabla \bar{\phi} +2\alpha_{j}\Im(\bar\phi\frac{\partial \phi}{\partial x_{1}})-(k^{2}\gamma(x)-\alpha_{j}^{2})|\phi|^2 dx-\sum_{n\in\mathbb{Z}}i\beta_{n}(|\phi^{+}_{n}|^2+|\phi^{-}_{n}|^2)=0. 
     \end{equation*}
     Thus, taking imaginary part of both sides, we obtain that
     \begin{equation}\label{nonprop}
         \sum_{n\in B_{\alpha_{j}}}\beta_{n}(|\phi^{+}_{n}|^2+|\phi^{-}_{n}|^2)=0.
     \end{equation}
     It follows that $\phi^{+}_{n}=\phi^{-}_{n}=0,n\in B_{\alpha_{j}}$. Now, letting $\xi\in Ker(D(\alpha_{j})^2)$, there is a propagating mode, $\eta\in H^1_{per}(\Omega_{H})$, such that $a_{\alpha_{j}}(\xi,\psi)=(\eta,\psi)_{*}, \forall \psi\in H^{1}_{per}(\Omega_{H})$ and $a_{\alpha_{j}}(\eta,\psi)=0, \forall \psi\in H^{1}_{per}(\Omega_{H})$. Since $\eta^{+}_{n}=\eta^{-}_{n}=0,n\in B_{\alpha_{j}}$
     \begin{equation*}
         (\eta,\eta)_{*}=a_{\alpha_{j}}(\xi,\eta)=\overline{a_{\alpha_{j}}(\eta,\xi)}=0.
     \end{equation*}
     namely,$\eta=0$, thus $a_{\alpha_{j}}(\xi,\psi)=0,\forall \psi\in H^{1}_{per}(\Omega_{H})$. That is,  $Ker(D(\alpha_{j})^2)\subset Ker(D(\alpha_{j}))$, which proves the assertion.
\end{proof}
We remark that by equation \eqref{nonprop}, the following corollary holds.
\begin{corollary}\label{corollary2}
    Under Assumption \ref{keyasump}, for all $\alpha_{j}\in \mathcal{P}(k)$, the corresponding propagating modes only have evanescent modes. 
\end{corollary}
Thus, $\alpha_{j}\in\mathcal{P}(k)$ are normal points of $D(\alpha)$. Furthermore, by Theorem 1.3.1 in Chapter 1 of \cite{MENNICKEN2003}, all $\alpha_{j}\in\mathcal{P}(k)$, are also normal points of $D^{-1}(\alpha)$. At these points, we need the finitely meromorphic Laurent expansion of the following form.  
\begin{lemma} $\forall\alpha_{j}\in P(k)$, there are finite rank operators $L^j_{m}:H^{1}_{per}(\Omega_{H})\rightarrow Ker(D(\alpha_{j}))$, $\dim(R(L^{j}_{m}))\leq\infty$,$m=1$,$\cdots$,$n_{j}$, and $H_{j}(\alpha)$ that are holomorphic in $B_{\delta_{j}}(\alpha_{j})$, such that $D^{-1}(\alpha)$ has the following Laurent expansion for $\alpha\in B_{\delta_{j}}(\alpha_{j})\backslash \{ \alpha_{j} \} $,
\begin{equation} \label{decompori}   
    D(\alpha)^{-1}=\sum_{m=1}^{rank(\phi_{j}^{1})}(\alpha-\alpha_{j})^{-m}L_{m}^j+H_{j}(\alpha).
\end{equation}
   Here, $rank(\phi_{j}^{1})$ is the maximal rank of all eigenvectors in $Ker(D(\alpha_{j}))$.
\end{lemma}
\begin{proof}
    Since $\alpha_{j}$ is the normal point of $D(\alpha)^{-1}$, consider the Laurent expansion of $D(\alpha)^{-1}$ at $\alpha_{j}$
    \begin{equation} \label{invdecomp}   
    D(\alpha)^{-1}=\sum_{m=-s}^{\infty}(\alpha-\alpha_{j})^{m}L_{m}^{j}.
\end{equation}
Since $D(\alpha_{j})D(\alpha)^{-1}\rightarrow I, \alpha\rightarrow\alpha_{j}$. We have $D(\alpha_{j})L_{m}^{j}=0, m=-s, \cdots, -1$, thus $R(L_{m}^{j})\subset Ker(D(\alpha_{j}))$.
Take $\phi\in Ker(D(\alpha_{j}))$, such that for some $\hat{\phi}\in H^{1}_{per}(\Omega_{H})$, we have $\phi=L^{j}_{-s}\hat{\phi}$. Thus, for $\Phi(\alpha)=(\alpha-\alpha_{j})^{s}D(\alpha)^{-1}\hat{\phi}$, such that $\Phi(\alpha_{j})=\phi$, and that $D(\alpha)\phi(\alpha)=(\alpha-\alpha_{j})^{s}\hat{\phi}$. It follows that $s\leq rank(\phi)$, which means that $s\leq rank(\phi_{j}^{1})$. Furthermore, if $s< rank(\phi_{j}^1)$, take $\phi(\alpha)$ such that $\phi(\alpha_{j})=\phi_{j}^{1}$, it follows that
  \begin{equation*}
      D(\alpha)\phi(\alpha)=(\alpha-\alpha_{j})^{rank(\phi_{j}^{1})}\psi(\alpha),~\psi(\alpha_j)\neq 0.
  \end{equation*}
  Using \eqref{invdecomp}, we obtain
  \begin{equation*}
      \phi(\alpha)=(\alpha-\alpha_{j})^{rank(\phi_{j}^{1})-s}\tilde{\psi}(\alpha).
  \end{equation*}
  therefore, $\phi(\alpha_{j})=0$, which is a contradiction. Finally, we have $s=rank(\phi_{j}^{1})$.
\end{proof}
\begin{definition}\cite{Ammari}\label{normality}
    For any simply connected region $\mathcal{V}\subset\mathbb{C}$ that have rectifiable boundary $\partial \mathcal{V}$, define
    \begin{eqnarray*}
        &&\mathcal{E}(\mathcal{V}):=\{S(\alpha)\in \mathcal{L}(H^{1}_{per}(\Omega_{H}))|\textit{$S(\alpha)$ is finitely meromorphic for $\alpha\in \mathcal{V}$, 
        is of Fredholm-type,}\\
        &&\qquad\qquad\textit{ and is continuous on $\partial \mathcal{V}$.}\}.
    \end{eqnarray*}
    If $S(\alpha)\in \mathcal{E}(\mathcal{V})$ is invertible for all but finitely many points $\bar{\mathcal{V}}$ we call $S(\alpha)$ normal with respect to $\partial \mathcal{V}$. We denote $\hat{\alpha}_{i}, i=1, \cdots, n$ the normal points of $S(\alpha)$ in$\mathcal{V}$, we can define the multiplicity of $S(\alpha)$ with respect to $\partial \mathcal{V}$
    \begin{equation*}
        \mathcal{M}(S(\alpha);\partial \mathcal{V}):=\sum_{i=1}^{n}M(S(\hat{\alpha}_{i})).
    \end{equation*}
\end{definition}
Under Definition \ref{normality}, we have
\begin{theorem}\label{thm5}
   Under Assumption \ref{rankfinity}, for all $\alpha_{j}\in \mathcal{P}(k)$, $D(\alpha)$ is normal with respect to $\partial B_{\delta_{PML}}(\alpha_{j})$. Denote $\mathcal{M}(D(\alpha);\partial B_{\delta_{PML}}(\alpha_{j}))=m_{j}$, then for a canonical system of eigenvectors of $Ker(D(\alpha_{j}))$ denoted by $\phi_{j}^{m}, m=1, \cdots, n_{j}$, we have
\begin{equation}
m_{j}=M(D(\alpha_{j}))=N(D(\alpha_{j}))=\sum_{m=1}^{n_{j}}rank(\phi_{j}^{m}).\label{regmult}
\end{equation}   
\end{theorem}
\begin{proof}
    $\forall \alpha_{h}\in\mathcal{P}(k)$, by Corollary \ref{analyprop} and the definition of $\delta_{PML}$\eqref{deltaPML}, $\overline{B_{\delta_{PML}}(\alpha_{j})}\subset B_{\delta_{j}}(\alpha_{j})$. Thus, $D(\alpha)$ is analytic and invertible in $\overline{B_{\delta_{PML}}(\alpha_{j}))}\backslash\{\alpha_{j}\}$ and is continuous on $\partial B_{\delta_{PML}}(\alpha_{j})$. In addition, $\alpha_{j}$ is the only normal point of $D(\alpha)$ in $B_{\delta_{PML}}(\alpha_{j}))$. It follows that $D(\alpha)$ is normal with respect to $\partial B_{\delta_{PML}}(\alpha_{j})$. By definition \ref{normality}, $\mathcal{M}(D(\alpha);\partial B_{\delta_{PML}}(\alpha_{j})):=m_{j}$. Thus, taking a canonical system of eigenvectors for $Ker(D(\alpha_{j}))$, denoted by $\phi_{j}^{m}$,$m=1$,$\cdots$,$n_{j}$, by Definition \ref{normality}, we can obtain \eqref{regmult}, which is what we have asserted.
\end{proof}

\section{Analysis of the eigenvalue perturbation}\label{sect5}
We need the following generalized Rouche's theorem, for a proof, see e.g. \cite{Ammari},
\begin{lemma}\cite{Ammari2010}\label{rouche}(Generalized Rouche's theorem) Assume that $V\in \mathbb{C}$ is a simply connected region with rectifiable boundary, $S(\alpha)\in \mathcal{L}(H^1_{per}(\Omega_{H}))$ is normal with respect to $\partial V$, If the operator-valued function $W(\alpha)$ is finitely meromorphic in $V$, is continuous on $\partial V$ and satisfies
\begin{equation*}
||S^{-1}(\alpha)W(\alpha)||_{*}<1, \alpha\in \partial V, 
\end{equation*} 
It follows that $S(\alpha)+W(\alpha)$ is normal with respect to $\partial V$, and
\begin{equation*}
\mathcal{M}(S(\alpha);\partial V) = \mathcal{M}(S(\alpha)+W(\alpha);\partial V).
\end{equation*}    
\end{lemma}  
\begin{lemma}\label{multiplicity}
Under Assumptions \ref{keyasump} and  \ref{rankfinity}, for all $\alpha_{j}\in P(k)$ and for $|\sigma|$ large enough $D_{\sigma}$ is normal with respect to $\partial B_{\delta_{PML}}(\alpha_{j})$. Furthermore,
\begin{equation*}
\mathcal{M}(D_{\sigma}(\alpha);\partial B_{\delta_{PML}}(\alpha_{j}))=m_{j}.
\end{equation*}     
\end{lemma}    
\begin{proof}
Consider
\begin{equation*}   
M_{\delta_{PML}}=\max_{j\in\mathcal{J}}\sup_{\alpha\in \partial B_{\delta_{PML}}(\alpha_{j})} \{ ||D^{-1}(\alpha)||_{*} \} . 
\end{equation*}    
By the definition of $\delta_{PML}$\eqref{deltaPML}, $\Delta_{\sigma}D(\alpha)$ is holomorphic in $B_{\delta_{PML}}(\alpha_{j})$, thus it is finitely meromorphic. Further, it is continuous on $\partial B_{\delta_{PML}}(\alpha_{j})$. By Theorem \ref{expdecay}, $||\Delta_{\sigma}D(\alpha)||_{*}$ is of exponential decay in $B_{\delta_{PML}}(\alpha_{j})$ with respect to $|\sigma|$. Taking $|\sigma|$ large enough, such that $\alpha\in\partial B_{\delta_{PML}}(\alpha_{j})$, $j\in \mathcal{J}$, $||D^{-1}(\alpha)\Delta_{\sigma}D(\alpha)||_{*}<M_{\delta_{PML}}||\Delta_{\sigma}D(\alpha)||_{*}<1$. By Theorem \ref{thm5}, $D(\alpha)$ is normal with respect to $\partial B_{\delta_{PML}}(\alpha_{j})$. Using Lemma \ref{rouche} for $D(\alpha)$, $\Delta_{\sigma}D(\alpha)$, we obtain that  
   \begin{equation*}
    \mathcal{M}(D(\alpha);\partial B_{\delta_{PML}}(\alpha_{j})) = \mathcal{M}(D(\alpha)+\Delta_{\sigma}D(\alpha);\partial B_{\delta_{PML}}(\alpha_{j}))=\mathcal{M}(D_{\sigma}(\alpha);\partial B_{\delta_{PML}}(\alpha_{j})).
\end{equation*}     
\end{proof}  
We further need the following definition from \cite{Ammari} of the trace of a finite rank operator, 
\begin{definition}\label{deftrace}
    Given a linear operator $F$ that has a finite rank in the Hilbert space $H$, it has an inner product, $(\cdot,\cdot)_{H}$ with norm $|\cdot|_{H}$. Thus, the coset of $Ker(F)$ is well-defined in $H$, we denote it by $\mathcal{C}$, and it satisfies $dim(\mathcal{C})<\infty$. The restriction of $F$ is denoted by $F|_{\mathcal{C}}$, the trace of $F|_{\mathcal{C}}$ is given by \cite{Kato1995}
    \begin{equation*}
trF|_{\mathcal{C}}=\operatorname{det}(F|_{\mathcal{C}}).
    \end{equation*}
    Taking a canonical system of basis on $C$, $\phi_{C}^{j}$,$j=1$,$\cdots$,$\operatorname{dim}(\mathcal{C})$, we have 
     \begin{equation}\label{fintrace}
    trF|_{\mathcal{C}}=\sum_{j=1}^{\operatorname{dim}(\mathcal{C})}(\phi_{C}^{j},F|_{\mathcal{C}}\phi_{C}^{j})_{H}.
    \end{equation}
    The trace of $F$ is given by
    \begin{equation*}
        tr(F):=tr(F|_{\mathcal{C}}).
    \end{equation*}
\end{definition}
Thus we can state the following generalized residue theorem, see \cite{Gohberg} for a proof.
  \begin{lemma}\label{residue} Assume that $S(\alpha)$    is normal with respect to   $\partial V$. If $f(\alpha)$   is analytic in     $V$   ,and is continuous in $\bar{V}$, we have 
   \begin{equation*}
\frac{1}{2\pi i}tr\int_{\partial V}f(\alpha)S^{-1}(\alpha)\frac{d}{d\alpha}S(\alpha)d\alpha = \sum_{i=1}^{\kappa}\mathcal{M}(S(\beta_{j}))f(\beta_{j}).
\end{equation*}    Here    $\beta_{j}$, $j=1$, $\cdots$, $\kappa$ are poles or eigenvalues of $S(\alpha)$ in $V$.  \end{lemma} 
Using the above generalized residue theorem, taking $S(\alpha)=D_{\sigma}(\alpha)$, $f(\alpha)=\alpha-\alpha_{j}$, for $m_{j}=1$, we have 
   \begin{equation}
(\alpha^{\sigma}_{j}-\alpha_{j})=\frac{1}{2\pi i} tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})(D_{\sigma})^{-1}(\alpha)\frac{d}{d\alpha}D_{\sigma}(\alpha)d\alpha . \label{tracest}
\end{equation}  

If $m_{j}>1$, by Lemma \ref{multiplicity}, for $|\sigma|$ large enough, all the eigenvalues $D_{\sigma}(\alpha)$ in $B_{\delta_{PML}}(\alpha_{j})$ are denoted by $\alpha_{i,j}^{\sigma}$, $i=1$, $\cdots$, $n_{j}^{\sigma}$, we further have $\sum_{i=1}^{n_{j}^{\sigma}}M(D_{\sigma}(\alpha_{i,j}^{\sigma}))=m_{j}$, thus
\begin{equation}
\sum_{i=1}^{n_{j}^{\sigma}}M(D_{\sigma}(\alpha^{\sigma}_{i,j}))(\alpha^{\sigma}_{i,j}-\alpha_{j})=\frac{1}{2\pi i} tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})(D_{\sigma})^{-1}(\alpha)\frac{d}{d\alpha}D_{\sigma}(\alpha)d\alpha . \label{multracest}
\end{equation}  
To complete the perturbation analysis, we thus need to give precise estimates on the right-hand side of \eqref{multracest},\eqref{tracest}. We thus need the following trace estimate.

\begin{lemma}\label{traceineq}(Trace estimate at the propagating values)  
For all $\alpha_{j}\in \mathcal{P}(k)$, if $S(\alpha)$ is analytic in $\overline{B_{\delta_{PML}}(\alpha_{j})}$, we have 
\begin{eqnarray}
&&|\frac{1}{2\pi i}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}D({\alpha})^{-1}S(\alpha)d\alpha| \nonumber\\
&&\leq C(\delta_{PML},rank(\phi_{j}^{1}),L_{\alpha_{j}},n_{j})\sup_{\alpha\in\partial B_{\delta_{PML}}(\alpha_{j})}||S(\alpha)||_{*}.\label{tracegood}
\end{eqnarray}     
Here, $rank(\phi_{j}^{1})$ is the largest rank of all eigenvectors $\phi$ in $Ker(D(\alpha_{j}))$, $n_{j}=dimKer(D(\alpha_{j}))$, and $L_{\alpha_{j}}$ is defined in \eqref{finupperbound}.
\end{lemma}    
   \begin{proof} Recalling \eqref{decompori}, $\forall\alpha_{j}\in P(k)$, there are finite rank operators $L^j_{m}:H^{1}_{per}(\Omega_{H})\rightarrow Ker(D(\alpha_{j}))$, $m=1$, $\cdots$, $rank(\phi_{j}^{1})$ and an analytic operator $H_{j}(\alpha)$ on $B_{\delta_{j}}(\alpha_{j})$, such that $D^{-1}(\alpha)$ has the following Laurent expansion in $\alpha\in B_{\delta_{j}}(\alpha_{j})\backslash \{ \alpha_{j} \} $,
\begin{equation*}     D(\alpha)^{-1}=\sum_{m=1}^{rank(\phi_{j}^{1})}(\alpha-\alpha_{j})^{-m}L_{m}^j+H_{j}(\alpha).
\end{equation*}
Since, $H_{j}(\alpha)$is holomorphic for $\alpha\in\overline{B_{\delta_{j}}(\alpha_{j})}$, $H_{j}(\alpha)S(\alpha)$ is analytic for $\alpha\in \overline{B_{\delta_{PML}}(\alpha_{j})}$, thus,
\begin{equation*}
\frac{1}{2\pi i}\int_{\partial B_{\delta_{PML}}(\alpha_{j})}H_{j}({\alpha})S(\alpha)d\alpha=0.
\end{equation*}
It follows that 
   \begin{equation}
\frac{1}{2\pi i}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}D({\alpha})^{-1}S(\alpha)d\alpha=\frac{1}{2\pi i}\sum_{m=1}^{rank(\phi_{j}^{1})}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})^{-m}L_m^j S(\alpha)d\alpha.\label{trrr}
\end{equation}  
Thus, taking $\phi_{j}^m\in Ker(D(\alpha_{j}))$, $m=1$, $\cdots$, $n_{j}$ as a canonical system of eigenvectors of $Ker(D(\alpha_{j}))$ with respect to the norm $||\cdot||_{*}$, by the definition of trace \eqref{fintrace}, we have 
   \begin{eqnarray*}
&&|\frac{1}{2\pi i}\sum_{m=1}^{rank(\phi_{j}^{1})}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})^{-m}L_m^j S(\alpha)d\alpha|\\
&&\leq \frac{1}{2\pi}\sum_{n=1}^{n_{j}}\sum_{m=1}^{rank(\phi_{j}^1)}|(\phi^{j}_{n},\frac{1}{2\pi}\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})^{-m}L_{m}^{j}S(\alpha)\phi^{j}_{n} d\alpha)_{*}|.
\end{eqnarray*}
Denote the right hand side by $I_{1}$, since 
\begin{eqnarray*}
    &&|(\phi^{j}_{n},\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})^{-m}L_{m}^{j}S(\alpha)\phi^{j}_{n} d\alpha)_{*}|\\
    &&\leq 2\pi\delta_{PML}^{1-m}||L_{m}^{j}||_{*}\sup_{\partial B_{\delta_{PML}}(\alpha_{j})}||S(\alpha)||_{*}.
\end{eqnarray*}
We denote 
\begin{equation}\label{finupperbound}
    L_{\alpha_{j}}=\sum_{m=1}^{rank(\phi_{j}^{1})}||L_m^j||_{*}.
\end{equation}
 Thus we have
\begin{eqnarray*}
I_{1}&\leq& n_{j}\sum_{m=1}^{rank(\phi_{j}^{1})}\delta_{PML}^{1-m}||L_m^j||_{*}\sup_{\alpha\in\partial B_{\delta_{PML}}(\alpha_{j})}||S(\alpha)||_{*}\\
&\leq &C(\delta_{PML},rank(\phi_{j}^{1}),L_{\alpha_{j}},n_{j})\sup_{\alpha\in\partial B_{\delta_{PML}}(\alpha_{j})}||S(\alpha)||_{*}.
\end{eqnarray*}    

Using the above inequality and \eqref{trrr}, we obtain \eqref{tracegood}.  
\end{proof}    

Now we are ready to present the perturbation theory. Firstly, using \eqref{tracest}, we consider the case for $m_{j}=1$ in the next theorem.
\begin{theorem}\label{singmult}(perturbation theory at $m_{j}=1$) Under Assumptions \ref{keyasump} and  \ref{rankfinity}, for $m_{j}=1$, there is $\gamma_{0}>0$, $\delta_{PML}>0$, for large enough $|\sigma|$, we have the following perturbation estimate for $\alpha_{j}\in \mathcal{P}(k)$,
   \begin{equation*}
|\alpha^{\sigma}_{j}-\alpha_{j}|\leq C(\delta_{PML},L_{\alpha_{j}},n_{j})e^{-\gamma_{0}\sqrt{k\delta_{PML}}|\sigma|}.
\end{equation*}     \end{theorem}    
   \begin{proof}Considering
   \begin{eqnarray*}
    \nonumber(D_{\sigma})^{-1}(\alpha)&=&(D_{\sigma}(\alpha)-D(\alpha)+D(\alpha))^{-1} \\  
   \nonumber& =&(D^{-1}(\alpha))(I+(D_{\sigma}(\alpha)-D(\alpha))D^{-1}(\alpha))^{-1} \\  
    &=&D^{-1}(\alpha)\sum_{p=0}^{\infty}(\Delta_{\sigma}D(\alpha)D^{-1}(\alpha))^{p},
    \end{eqnarray*}    by Theorem \ref{expdecay}, we pick $|\sigma|$ large enough, such that the Neumann series is convergent on $\partial B_{\delta_{PML}}(\alpha_{j})$. Using  \eqref{tracest}, we have 
   \begin{eqnarray*}
&&\alpha_{j}^{\sigma}-\alpha_{j}\\
&=&\frac{1}{2\pi }\sum_{p=0}^{\infty}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})D^{-1}(\alpha)(-\Delta_{\sigma}D(\alpha)D^{-1}(\alpha))^{p})\frac{d}{d\alpha}(D(\alpha)+\Delta_{\sigma}D(\alpha))d\alpha.
\end{eqnarray*}   
Since $\alpha_{j}$    is the only propagating value of     $D(\alpha)$    in    $B_{\delta_{PML}}(\alpha_{j})$, we can obtain
   \begin{equation*}
\frac{1}{2\pi }tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})D^{-1}(\alpha)\frac{d}{d\alpha}(D(\alpha))d\alpha =0.
\end{equation*}    
Using the partial integration, we have
   \begin{equation*}
|\alpha^{\sigma}_{j}-\alpha_{j}|=\frac{1}{2\pi}\sum_{p=0}^{\infty}tr\int_{\partial B_{\delta_{PML}}(\alpha_{j})}(\alpha-\alpha_{j})\frac{d}{d\alpha}[D(\alpha)^{-1}\Delta_{\sigma}D(\alpha)]^{p}d\alpha.
\end{equation*}    
By theorem \ref{expdecay},
\begin{equation*}
||\Delta_{\sigma}D(\alpha)||_{*}\leq \exp(-\gamma_{0}\sqrt{\delta_{PML}}|\sigma|\sqrt{|k|}),
\end{equation*}   
Finally, using lemma \ref{traceineq} on $\Delta_{\sigma}D(\alpha)$, we have 
   \begin{eqnarray*}
    |\alpha^{\sigma}_{j}-\alpha_{j}|&\leq & |tr\frac{C}{2\pi }\int_{\partial B_{\delta_{PML}}(\alpha_{j})}D^{-1}(\alpha)\Delta_{\sigma}D(\alpha)d\alpha| \\  &+& O(e^{-2\gamma_{0}\sqrt{\delta_{PML}}|\sigma|\sqrt{|k|}} \\ 
&\leq& C(\delta_{PML},L_{\alpha_{j}},n_{j})e^{-\gamma_{0}\sqrt{k\delta_{PML}}|\sigma|}.
\end{eqnarray*}
This finishes the proof.
  \end{proof}    
Using \eqref{multracest}, similar to the proof of Theorem \ref{singmult}, we can obtain the following result. 
\begin{theorem}(For $m_{j}>1$)Under Assumptions \ref{keyasump} and  \ref{rankfinity}, there is $\gamma_{0}>0$, $\delta_{PML}>0$, for large enough $|\sigma|$, the following estimate holds for all $\alpha_{j}\in P(k)$
   \begin{equation*}
|\sum_{i=1}^{n_{j}^{\sigma}}M(D_{\sigma}(\alpha^{\sigma}_{i,j}))(\alpha^{\sigma}_{i,j}-\alpha_{j})|\leq C(\delta_{PML},rank(\phi_{j}^{1}),L_{\alpha_{j}},n_{j})e^{-\gamma_{0}\sqrt{k\delta_{PML}}|\sigma|}.
\end{equation*}  
\end{theorem}
\section{Discretization of the PML problem}\label{sect6}  
In this section, we transform the PML problem into a block matrix representation, then perform the finite element discretization, and obtain the final numerical format as well as its finite element discretization error.
\subsection{Block matrix representation of the PML problem}
For all $\phi, \psi \in H^1_{per}(\tilde{\Omega}_H)$, let  
\begin{eqnarray*}
    &&a_{1}(\phi,\psi)=\int_{\tilde{\Omega}_H}s(x_{2})\frac{\partial \phi}{\partial x_{1}} \cdot\frac{\partial \bar{\psi}}{\partial x_{1}} +\frac{1}{s(x_{2})}\frac{\partial \phi}{\partial x_{2}} \cdot\frac{\partial \bar{\psi}}{\partial x_{2}} -k^2(\gamma(x)) s(x_{2})\phi\bar{\psi}dx, \\ 
    &&a_{2}(\phi,\psi)=-2i\int_{\tilde{\Omega}_H}s(x_{2})\frac{\partial \phi}{\partial x_{1}}\bar\psi dx, \\ 
    &&a_{3}(\phi,\psi)=\int_{\tilde{\Omega}_H}s(x_{2})\phi\bar{\psi}dx.
\end{eqnarray*}    
We can rewrite the problem \eqref{Dpblm} as: find nonvanishing $\phi\in X_{per}(\tilde{\Omega}_H)$ and $\alpha\in\mathbb{C}$ such that
\begin{equation}
    a_{\alpha,\tilde{\Omega}_{H}}(\phi,\psi)=a_{1}(\phi,\psi)+\alpha a_{2}(\phi,\psi)+\alpha^2 a_{3}(\phi,\psi)=0, ~\forall\psi\in X_{per}(\tilde{\Omega}_H). \label{Dpblm1} 
\end{equation}    
Now we introduce $\eta \in X_{per}(\tilde{\Omega}_H)$ satisfying
\begin{equation*}
(\eta,\xi)_{H^1_{per}(\tilde{\Omega}_H)}= \alpha(\phi,\xi)_{H^1_{per}(\tilde{\Omega}_H)}, ~\forall \xi\in X_{per}(\tilde{\Omega}_H).
\end{equation*}
Then , we get the block matrix representation of \eqref{Dpblm1}: find nonvanishing $\phi,\eta\in X_{per}(\tilde{\Omega}_H)$ and $\alpha\in\mathbb{C}$ such that
\begin{equation}
    \begin{bmatrix}
         a_{1}(\phi,\psi)  \\ 
        (\eta(\alpha),\xi)_{H^1_{per}(\tilde{\Omega}_H)}
    \end{bmatrix}
    =\alpha
    \begin{bmatrix}
         -a_{2}(\phi,\psi)   -a_{3}(\eta,\psi) \\ 
         (\phi(\alpha),\xi)_{H^1_{per}(\tilde{\Omega}_H)}  
    \end{bmatrix}, ~\forall \xi,\psi \in X_{per}(\tilde{\Omega}_H).
    \label{blockeig0}
\end{equation}  
To analyze the characteristic value problem of the block matrix representation, we need the following Garding-type inequality.
\begin{theorem} \label{thm8} The bilinear form $a_{1}(\phi,\psi), \phi, \psi \in X_{per}(\tilde{\Omega}_H)$ satisfies
\begin{equation}
    \Re a_{1}(\phi,\phi) \geq C_{0}||\phi||_{H^1_{per}(\tilde{\Omega}_H)}^2 - C_{1}||\phi||_{L^2_{per}(\tilde{\Omega}_H)}. \label{coer}
\end{equation} 
Where $C_0, C_1$ are constants depending on 
$\|s(x_2)\|_{L^\infty(\tilde{\Omega}_H)}, k$ and $\max_{x\in\tilde{\Omega}_H}\gamma(x)$.
\end{theorem}    
\begin{proof} For all $\phi \in X_{per}(\tilde{\Omega}_H)$, let
\begin{eqnarray*}
    \Re a_{1}(\phi,\phi) &=& \int_{\tilde{\Omega}_H} \Re (s(x_{2}))(|\frac{\partial \phi}{\partial x_{1}}|^2 + \frac{1}{|s(x_{2})|^2}|\frac{\partial \phi}{\partial x_{2}}|^2 - k^2\gamma(x)|\phi|^2)dx \\ 
    &\geq& \min_{x \in \tilde{\Omega}_H}|\frac{1}{s(x_{2})}|^2(\|\frac{\partial \phi}{\partial x_{1}}\|^2_{L^2(\tilde{\Omega}_H)} + \|\frac{\partial \phi}{\partial x_{2}}\|_{L^2(\tilde{\Omega}_H)}^2) \\
    &-& k^2(\max_{x \in \tilde{\Omega}_H}(\gamma(x))  \max_{x \in \tilde{\Omega}_H}(\Re |s(x_{2})|))||\phi||^2_{L^2(\tilde{\Omega}_H)}.
\end{eqnarray*}    
Therefore, there exist $C_{0} = C_{0}(\|s(x_2)\|_{L^\infty})$, $C_{1} = C_1(C_{0},\|s(x_2)\|_{L^\infty}, k, \max_{x \in \tilde{\Omega}_H}(\gamma(x)))$, such that \eqref{coer} holds.  
\end{proof}    
By Theorem \ref{thm8}, according to the Riesz representation theorem, there exist linear operators $A_{\sigma}, B_{\sigma}, C_{\sigma}: X_{per}(\tilde{\Omega}_H) \rightarrow X_{per}(\tilde{\Omega}_H)$, such that the block representation becomes
\begin{equation}
    \begin{bmatrix}
(A_{\sigma}\phi(\alpha),\psi)_{H^1_{per}(\tilde{\Omega}_H)}  \\ 
        (\eta(\alpha),\xi)_{H^1_{per}(\tilde{\Omega}_H)}
    \end{bmatrix}
    =\alpha
    \begin{bmatrix}
         -(B_{\sigma}\phi(\alpha),\psi)_{H^1_{per}(\tilde{\Omega}_H)}  -(C_{\sigma}\eta(\alpha),\psi)_{H^1_{per}(\tilde{\Omega}_H)} \\ 
         (\phi(\alpha),\xi)_{H^1_{per}(\tilde{\Omega}_H)}  
    \end{bmatrix}.
    \label{blockeig}
\end{equation}  
Therefore, let
\begin{equation*}
    \mathcal{M}_{\sigma}^{0}=
    \begin{bmatrix}
         A_{\sigma} & 0 \\ 
        0 & I
    \end{bmatrix},~
    \mathcal{M}_{\sigma}^{1}=
    \begin{bmatrix}
         -B_{\sigma} &  -C_{\sigma} \\ 
         I  & 0
    \end{bmatrix}.
\end{equation*}    
Here, $\mathcal{M}_{\sigma}^{i}$, $i=0,1$ are operators from $X_{per}(\tilde{\Omega}_H) \times X_{per}(\tilde{\Omega}_H) \rightarrow X_{per}(\tilde{\Omega}_H) \times X_{per}(\tilde{\Omega}_H)$. Then \eqref{blockeig} is equivalent to
\begin{equation*}
(\mathcal{M}_{\sigma}^{0}\Phi(\alpha),\Psi)_{1}=\alpha(\mathcal{M}_{\sigma}^{1}\Phi(\alpha),\Psi)_{1}, \forall \Psi \in X_{per}(\tilde{\Omega}_H) \times X_{per}(\tilde{\Omega}_H).
\end{equation*}
Here $\Phi(\alpha) = (\phi(\alpha), \eta(\alpha)), \phi(\alpha), \eta(\alpha) \in X_{per}(\tilde{\Omega}_H)$, $\Psi = (\psi, \xi), \psi, \xi \in X_{per}(\tilde{\Omega}_H)$ and $(\Phi, \Psi)_{1} = (\phi, \psi)_{
H^1_{per}(\tilde{\Omega}_H)} + (\eta, \xi)_{H^1_{per}(\tilde{\Omega}_H)}$. Thus, $\mathcal{M}_{\sigma}^{0}$ is an isomorphism.
Then, we can define $\mathcal{L}_{\sigma} = (\mathcal{M}_{\sigma}^{0})^{-1}\mathcal{M}_{\sigma}^1$. Therefore, the generalized eigenvalue problem \eqref{blockeig0} becomes a linear eigenvalue problem of finding the eigenvalues $\mu_{j}^{\sigma} = \frac{1}{\alpha_{j}^{\sigma}}$ of $\mathcal{L}_{\sigma}$.

\subsection{Finite element discretization}
Now we consider the finite element approximation of the block matrix equation \eqref{blockeig}. Let $M_{0}$ represent the matrix on the left side of the equation, and let $M_{1}$ represent the matrix on the right side. Take $\lbrace \mathcal{M}_{h}\rbrace$ as a regular triangulation of the domain $\tilde{\Omega}_H$, where $h>0$ is the longest side of all triangles. Furthermore, assume that any triangle $T$ must be completely contained in $\overline{\Omega_{+}^{PML}}$, $\overline{\Omega_{-}^{PML}}$, or $\overline{\Omega}$. The nodal basis functions corresponding to the triangulation $\{ \mathcal{M}_{h} \}$ are denoted as $\psi_{i}\in V_{h}(\tilde{\Omega}_H)$, $i=1$, $\cdots$, $N$.  We take $V_{h}(\tilde{\Omega}_H)\subset X_{per}(\tilde{\Omega}_H))$ as a space composed of first-order linear elements. In actual calculations, appropriate adjustments at the left and right boundaries can make space $V_{h}(\tilde{\Omega}_H)$ satisfy the periodic boundary conditions in the $x_{1}$ direction \cite{ChenWu}. Furthermore,
\begin{equation*}
    \lim_{h\rightarrow 0}inf_{u_{h}\in V_{h}(\tilde{\Omega}_H)}||u-u_{h}||_{H_{per}^{1}(\tilde{\Omega}_H)}=0,  \textit{ for all }         u\in X_{per}(\tilde{\Omega}_H),
\end{equation*} since linear finite element functions belong to $C^{0}(\tilde{\Omega}_H)$ over the entire computational domain $\tilde{\Omega}_{H}$, this makes them belong to $H^1(\tilde{\Omega}_H)$.
Next, discretize the equation by taking $\phi_{h}=\sum_{i=1}^{N}\gamma_{i}\psi_{i}$, $\eta_{h}=\sum_{i=1}^{N}\xi_{i}\psi_{i}$ to represent the finite element interpolation functions corresponding to $\phi, \eta \in X_{per}(\tilde{\Omega}_H)$. Substituting them into \eqref{blockeig} gives the PML truncation propagation value problem under finite element discretization: find $\alpha$ such that there exist non-zero $\hat{\gamma}, \hat{\xi}$ satisfying,
\begin{equation}\label{disblockdiag}
    \begin{bmatrix}
        A^{h}_{\sigma} & 0 \\ 
        0 & P^{h}
    \end{bmatrix}\begin{bmatrix}
    \hat{\gamma} \\ 
    \hat{\xi}
    \end{bmatrix}
    =\alpha
    \begin{bmatrix}
        -B^{h}_{\sigma} & -C^{h}_{\sigma} \\ 
        P^{h} & 0
    \end{bmatrix}\begin{bmatrix}
    \hat{\gamma} \\ 
    \hat{\xi}
    \end{bmatrix}.
\end{equation}    
Here the $(i,j)$ entries of matrix $A^h_\sigma, B^h_\sigma, C^h_\sigma$ and $P^h$ are 
$$ a_{1}(\psi_{j},\psi_{i}),  a_{2}(\psi_{j},\psi_{i}), a_{3}(\psi_{j},\psi_{i}), \mbox{ and }(\psi_{j},\psi_{i})_{H^1_{per}(D)}$$
respectively.
%\begin{eqnarray*}
%&A^{h}_{\sigma}= \{ a_{1}(\psi_{i},\psi_{j}) \} ,i,j=1\cdots N \\ 
%&B^{h}_{\sigma}= \{ a_{2}(\psi_{i},\psi_{j}) \} ,i,j=1\cdots N \\ 
%&C^{h}_{\sigma}= \{ a_{3}(\psi_{i},\psi_{j}) \} ,i,j=1\cdots N \\ 
%&P^{h}= \{ (\psi_{i},\psi_{j})_{H^1_{per}(D)} \} ,i,j=1\cdots N.
%\end{eqnarray*}   

\begin{comment}

Using the above representation, we can further define the operators $\mathcal{M}_{\sigma,h}^{i},i=0,1$ corresponding to the left and right block operators as $V_{h}(\tilde{\Omega}_H)\times V_{h}(\tilde{\Omega}_H)\rightarrow V_{h}(\tilde{\Omega}_H)\times V_{h}(\tilde{\Omega}_H)$. \eqref{disblockdiag} is equivalent to
\begin{equation*}
        (\mathcal{M}_{\sigma,h}^{0}\Phi_{h}(\alpha),\Psi_{h})_{1}=\alpha(\mathcal{M}_{\sigma,h}^{1}\Phi_{h}(\alpha),\Psi)_{1}, \forall \Psi\in V_{h}(\tilde{\Omega}_H)\times V_{h}(\tilde{\Omega}_H).
\end{equation*}    
Using the above representation, we can also define an operator $L_{\sigma}^{h}=(\mathcal{M}_{\sigma,h}^{0})^{-1}\mathcal{M}_{\sigma,h}^{1}$. The convergence is guaranteed by the following theorem from \cite{Engstrom1}.
\begin{theorem}\label{thm10} The discrete block operator $L_{\sigma}^h$ under finite element discretization converges to $L_{\sigma}$ in the norm induced by the $H^1_{per}(\tilde{\Omega}_H)$ space. \end{theorem}    
\end{comment}

Next, we will consider the convergence of the finite element approximation. In the following, $\|\cdot\|$ denotes the operator norm of the bounded linear operator from $ X_{per}(\tilde{\Omega}_H)$ to itself.

By the Garding inequality and Riesz representation theorem, there exists an invertible operator $ J_{\sigma} $ and a compact operator $ K_{\sigma}: X_{per}(\tilde{\Omega}_H) \rightarrow X_{per}(\tilde{\Omega}_H) $ such that $ A_{\sigma} = J_{\sigma} + K_{\sigma} $, and $ \Re (J_{\sigma} \phi, \phi)_{H^1_{per}(\tilde{\Omega}_H)} \ge C_0 \Vert \phi \Vert_{H^1_{per}(\tilde{\Omega}_H)}^2 $ for all $ \phi \in X_{per}(\tilde{\Omega}_H) $.
Let $J_h\in\mathbb{C}^{N\times N}$ whose $(i,j)$ entry is given by $ (\psi_j, J_{\sigma}^* \psi_i)_{H^1_{per}(\tilde{\Omega}_H)} $. For any $\phi\in X_{per}(\tilde{\Omega}_H)$, We consider the following linear system
\begin{equation*}
J_h \phi_p = \phi_J,
\end{equation*}
where $\phi_J\in \mathbb{C}^N$ and $\phi^J_i=(\phi, J_{\sigma}^* \psi_i)_{H^1_{per}(\tilde{\Omega}_H)}$. Since $J_\sigma$ is invertible, it is easy to verify that $J_h$ is invertible. Then there exists a unique $\phi_p\in\mathbb{C}^N$
that satisfies the above linear system. Now we can define the operator $ \mathcal{P}_{\sigma}^h: X_{per}(\tilde{\Omega}_H) \rightarrow V_h(\tilde{\Omega}_H) $ by $ \mathcal{P}_{\sigma}^h \phi = \begin{bmatrix} \psi_1 & \psi_2 & \cdots & \psi_N \end{bmatrix} \phi_p $. Then
\begin{equation*}
(\mathcal{P}_{\sigma}^h \phi, J_{\sigma}^* \psi)_{H^1_{per}(\tilde{\Omega}_H)} = (\phi, J_{\sigma}^* \psi)_{H^1_{per}(\tilde{\Omega}_H)}, \quad \forall \phi \in X_{per}(\tilde{\Omega}_H), \psi \in V_h(\tilde{\Omega}_H).
\end{equation*}
For the family of operators $ \{ \mathcal{P}_{\sigma}^h \}_{h > 0} $, we can show that it is a uniformly bounded family of operators converging pointwisely to $ I $. Consequently, for any compact operator $ T: X_{per}(\tilde{\Omega}_H) \rightarrow X_{per}(\tilde{\Omega}_H) $, we have $ \lim\limits_{h \to 0} \Vert \mathcal{P}_{\sigma}^h T - T \Vert = 0 $. The details of the proof can be found in the Appendix.

With the help of $\mathcal{P}_h$, we define $ \tilde{A}_{\sigma}^h = J_{\sigma} + J_{\sigma} \mathcal{P}_{\sigma}^h J_{\sigma}^{-1} K_{\sigma} $, $ \tilde{B}_{\sigma}^h = J_{\sigma} \mathcal{P}_{\sigma}^h J_{\sigma}^{-1} B_{\sigma} $, and $ \tilde{C}_{\sigma}^h = J_{\sigma} \mathcal{P}_{\sigma}^h J_{\sigma}^{-1} C_{\sigma} $. For any $ \phi \in X_{per}(\tilde{\Omega}_H) $ and $ \psi \in V_h(\tilde{\Omega}_H) $, we have
\begin{equation*}
(\tilde{A}_{\sigma}^h \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)} = (\phi + \mathcal{P}_{\sigma}^h J_{\sigma}^{-1} K_{\sigma} \phi, J_{\sigma}^* \psi)_{H^1_{per}(\tilde{\Omega}_H)} = (A_{\sigma} \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)}.
\end{equation*}
Similarly, it can be shown that $ (\tilde{B}_{\sigma}^h \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)} = (B_{\sigma} \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)} $ and $ (\tilde{C}_{\sigma}^h \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)} = (C_{\sigma} \phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)} $ for any $ \phi \in X_{per}(\tilde{\Omega}_H) $ and $ \psi \in V_h(\tilde{\Omega}_H) $.

Since $ K_\sigma, B_{\sigma}, C_{\sigma} $ are compact operators, in the operator norm sense, as $ h \to 0^+ $, we have $ \tilde{A}_{\sigma}^h \to A_{\sigma} $, $ \tilde{B}_{\sigma}^h \to B_{\sigma} $, and $ \tilde{C}_{\sigma}^h \to C_{\sigma} $. Thus, for sufficiently small $ h $, the operator $ \tilde{A}_{\sigma}^h $ is invertible, and we can define
\begin{equation*}
\tilde{L}_{\sigma}^h = \begin{bmatrix} \tilde{A}_{\sigma}^h & 0 \\ 0 & I \end{bmatrix}^{-1} \begin{bmatrix} -\tilde{B}_{\sigma}^h & -\tilde{C}_{\sigma}^h \\ I & 0 \end{bmatrix}.
\end{equation*}
Then$ \lim\limits_{h \to 0} \tilde{L}_{\sigma}^h = L_{\sigma} $ in the operator norm sense.

Consider the following quadratic eigenvalue problem: find nonvanishing $ \phi \in X_{per}(\tilde{\Omega}_H) $ and $ \alpha \in \mathbb{C} $ such that
\begin{equation}\label{toquadeig}
        (\tilde{A}^{h}_{\sigma}+\alpha\tilde{B}^{h}_{\sigma}+\alpha^2\tilde{C}^{h}_{\sigma})\phi=0.
    \end{equation}
For sufficiently small $ h $, this is equivalent to the eigenvalue problem of the operator $ \tilde{L}_{\sigma}^h $. Since $J_\sigma$ is invertible, the equation can also be written as
\begin{equation*}
\phi = -\mathcal{P}_{\sigma}^h J_{\sigma}^{-1} (K_{\sigma} + \alpha B_{\sigma} + \alpha^2 C_{\sigma}) \phi.
\end{equation*}
This tells us that the eigenfunction of $\tilde{L}_\sigma^h$ must be in $ V_h(\tilde{\Omega}_H)$.
Thus, we restrict $ \phi $ to $ V_h(\tilde{\Omega}_H) $ in $ V_h(\tilde{\Omega}_H) $,  and in weak sense
\eqref{toquadeig} can be written as:
\begin{equation}\label{toquadeig1}
((\tilde{A}^{h}_{\sigma}+\alpha\tilde{B}^{h}_{\sigma}+\alpha^2\tilde{C}^{h}_{\sigma})\phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)}=0. ~\forall \psi\in V_h(\tilde{\Omega}_H).
    \end{equation}
By the definitions of $\tilde{A}^{h}_{\sigma},\tilde{B}^{h}_{\sigma},\tilde{C}^{h}_{\sigma}$, we can easily find that \eqref{toquadeig1} equals to
\begin{equation*}
((A_{\sigma}+\alpha B_{\sigma}+\alpha^2C_{\sigma})\phi, \psi)_{H^1_{per}(\tilde{\Omega}_H)}=0. ~\forall \psi\in V_h(\tilde{\Omega}_H).
    \end{equation*}
Which is just the quadratic eigenvalue problem according to problem \eqref{disblockdiag}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Note that the special form of the left block diagonal matrix in \eqref{disblockdiag} allows the matrix eigenvalue problem to be written as
\begin{equation}
    \begin{bmatrix}
        A^{h}_{\sigma} & 0 \\ 
        0 & I^{h}
    \end{bmatrix}\begin{bmatrix}
    \hat{\gamma} \\ 
    \hat{\xi}
    \end{bmatrix}
    =\alpha
    \begin{bmatrix}
        -B^{h}_{\sigma} & -C^{h}_{\sigma} \\ 
        I^h & 0
    \end{bmatrix}\begin{bmatrix}
    \hat{\gamma} \\ 
    \hat{\xi}
    \end{bmatrix}.\label{disblockdiag1}
\end{equation}    
Here, $I^h$ is the identity matrix on the finite-dimensional space. In this way, we obtain the generalized eigenvalue problem corresponding to the PML problem.

\subsection{Discretization error}   
For each $\mu^{\sigma}$ (which is an eigenvalue of $L_{\sigma}$), take a contour $C_{{\mu}^{\sigma}}$ such that on $C_{{\mu}^{\sigma}}$, $L_{\sigma}$ is invertible, and within the bounded region contained by $C_{{\mu}^{\sigma}}$, $L_{\sigma}$ has and only has the eigenvalue $\mu^{\sigma}$. Similarly, $C_{\bar{\mu}^{\sigma}}$ can be taken. From this, we define two eigenvalue projections $E({\mu}^{\sigma}), E^{*}(\bar{\mu}^{\sigma})$ following the definition in \cite{Engstrom1}:
\begin{eqnarray*}
    E(\mu^{\sigma})=\frac{1}{2\pi i}\int_{C_{\mu^{\sigma}}}(z-L_{\sigma})^{-1}dz, \\ 
    E^{*}(\bar{\mu}^{\sigma})=\frac{1}{2\pi i}\int_{C_{\bar{\mu}^{\sigma}}}(z-L^{*}_{\sigma})^{-1}dz.
\end{eqnarray*}   
Here, $E(\mu^{\sigma}):V_{h}(\tilde{\Omega}_H)\rightarrow V_{h}(\tilde{\Omega}_H)$, $E^{*}(\bar{\mu}^{\sigma}):V_{h}(\tilde{\Omega}_H)\rightarrow V_{h}(\tilde{\Omega}_H)$, and their ranges are
\begin{equation*}
    R_{\mu^{\sigma}}:=Ker(\mu^{\sigma}-L_{\sigma})^{r}, R^{*}_{\bar{\mu}^{\sigma}}:=Ker(\bar{\mu}^{\sigma}-L^{*}_{\sigma})^{r}.
\end{equation*}   
Here, $r$ is the Riesz number of the operators $\mu^{\sigma}-L_{\sigma}$ and $\bar{\mu}^{\sigma}-L_{\sigma}^{*}$. In addition, a distance measure between two spaces is introduced
\begin{equation*}
d(V_{1},V_{2})=\sup_{v_{1}\in V_{1}}\inf_{v_{2}\in V_{2}}\frac{||v_{1}-v_{2}||_{H^{1}_{per}(\tilde{\Omega}_H)}}{||v_{1}||_{H^1_{per}(\tilde{\Omega}_H)}}.
\end{equation*}    
Therefore, it can be recorded as
\begin{equation*}
\gamma_{h}=d(R_{\mu_{\sigma}},V_{h}(\tilde{\Omega}_H)),~\gamma_{h}^{*}=d(R^{*}_{\mu_{\sigma}},V_{h}(\tilde{\Omega}_H)) .
\end{equation*}    
For first-order linear elements, there exist $C,C^{*}$ related only to the dimension and $\tilde {\Omega}_{H}$ such that $\gamma_{h}\leq Ch$, $\gamma_{h}^{*}\leq C^{*}h$ \cite{Brenner,ChenWu}.
Thus, let $N_{\sigma}=dim R_{\mu^{\sigma}}$, and let $\mu^{\sigma}_{k}$, $k=1$, $\cdots$, $N_{\sigma}$ be the corresponding eigenvalues of $\mu^{\sigma}$ calculated by finite element discretization, then by \cite[Equation (95)]{Engstrom1}, we have
\begin{equation}
\max_{i=1,\cdots,N_{\sigma}}||\mu^{\sigma}-\mu^{\sigma}_{i}||\leq C (\gamma_h\gamma_{h}*)^{\frac{1}{r}}\leq C h^{\frac{2}{r}}.\label{covrate} 
\end{equation}     

Note that the Riesz number of $\alpha_{j}$ with respect to $D(\alpha)$ is 1, but the Riesz number of $D_{\sigma}(\alpha)$ at the corresponding eigenvalues $\alpha_{i,j}^{\sigma}$, $i=1$, $\cdots$, $n_{j}^{\sigma}$ could be greater than 1. Therefore, in actual calculation, the convergence rate of the propagation value may be lower than second-order. 

\section{Numerical experiments} \label{sect7} 
In this section, we consider two numerical experiments to verify the effectiveness of our method. We use the Matlab function $eigs$ to solve the eigensystem \eqref{disblockdiag1} to compute the propagating values and the corresponding modes. First, in the following experiments, for the period $\Lambda=2\pi$, we choose the PML thickness to be $L=0.5$ and set $s(x_{2})$ accordingly, making the PML truncation error negligible compared to finite element discretization. In all experiments, the nonhomogeneous periodic medium of the Wigner-Seitz cell is in $[-\pi,\pi]\times[-0.5,0.5]$.  Since the periodic $\Lambda$ is $2\pi$, the propagating values are all in the interval $[-0.5, 0.5]$.  
