            e^{-3ix_1} \sin{(\sqrt{\gamma k^2-(\alpha_1-3)^2}x_2)},  &-\frac{1}{2}<x_2<\frac{1}{2}, \\
             -e^{-3ix_1}   \sin{\sqrt{\frac{\gamma k^2-(\alpha_1-3)^2}{2}}}e^{\sqrt{(\alpha_1-3)^2-k^2}(x_2+\frac12)},  & x_2<-\frac{1}{2}.        
        \end{array}
    \end{cases}
\end{equation*}

\begin{equation*}
    u_{prop}^{(2)}(x)=e^{i\alpha_2x_1}\begin{cases}
        \begin{array}{cc}
        e^{4ix_1}   \cos{\sqrt{\frac{\gamma k^2-(\alpha_2+4)^2}{2}}}e^{-\sqrt{(\alpha_2+4)^2-k^2}(x_2-\frac12)},  & x_2>\frac{1}{2}, \\
            e^{4ix_1} \cos{(\sqrt{\gamma k^2-(\alpha_2+4)^2}x_2)},  &-\frac{1}{2}<x_2<\frac{1}{2}, \\
             e^{4ix_1}   \cos{\sqrt{\frac{\gamma k^2-(\alpha_2+4)^2}{2}}}e^{\sqrt{(\alpha_2+4)^2-k^2}(x_2+\frac12)},  & x_2<-\frac{1}{2}.        
        \end{array}
    \end{cases}
\end{equation*}

