\begin{appendices}
\section*{Appendix: convergence of operator $\mathcal{P}_h$}
Below are two propositions concerning operator $\mathcal{P}_{\sigma}^h$.

\begin{itemize}
    \item The family $ \{ \mathcal{P}_{\sigma}^h \}_{h > 0}$ is uniformly bounded, and as $ h \to 0^+ $, $ \{ \mathcal{P}_{\sigma}^h \}_{h > 0} $ converges pointwisely to $ I $. This is because that, $\forall \phi \in X_{per}(\tilde{\Omega}_H), \psi \in V_h(\tilde{\Omega}_H)$, 
    \begin{equation*}
    \begin{aligned}
    \Vert \mathcal{P}_{\sigma}^h \phi - \psi \Vert_{H^1_{per}(\tilde{\Omega}_H)} &\le \frac{\Re (J_{\sigma} (\mathcal{P}_{\sigma}^h \phi - \psi), \mathcal{P}_{\sigma}^h \phi - \psi)_{H^1_{per}(\tilde{\Omega}_H)}}{C_0 \Vert \mathcal{P}_{\sigma}^h \phi - \psi \Vert_{H^1_{per}(\tilde{\Omega}_H)}} \\
    &= \frac{\Re (J_{\sigma} (\phi - \psi), \mathcal{P}_{\sigma}^h \phi - \psi)_{H^1_{per}(\tilde{\Omega}_H)}}{C_0 \Vert \mathcal{P}_{\sigma}^h \phi - \psi \Vert_{H^1_{per}(\tilde{\Omega}_H)}}
    \le \frac{\Vert J_{\sigma} \Vert}{C_0} \Vert \phi - \psi \Vert_{H^1_{per}(\tilde{\Omega}_H)}.
    \end{aligned}
    \end{equation*}
    Therefore, $ \Vert \mathcal{P}_{\sigma}^h \Vert \le \frac{\Vert J_{\sigma} \Vert}{C_0} $, and
    \begin{equation*}
    \lim_{h \to 0} \Vert \mathcal{P}_{\sigma}^h \phi - \phi \Vert_{H^1_{per}(\tilde{\Omega}_H)} \le \left(1 + \frac{\Vert J_{\sigma} \Vert}{C_0}\right) \lim_{h \to 0} \inf_{\psi \in V_h(\tilde{\Omega}_H)} \Vert \phi - \psi \Vert_{H_{per}^1(\tilde{\Omega}_H)} = 0.
    \end{equation*}

    \item For any compact operator $ T: X_{per}(\tilde{\Omega}_H) \rightarrow X_{per}(\tilde{\Omega}_H) $, we have $ \lim_{h \to 0} \Vert \mathcal{P}_{\sigma}^h T - T \Vert = 0 $.

    Suppose otherwise, there exist $ \epsilon_0 > 0 $, $ h_n > 0 $, and $ x_n \in X_{per}(\tilde{\Omega}_H) $, such that
    \begin{equation*}
    h_n \to 0, \quad \Vert x_n \Vert_{H^1_{per}(\tilde{\Omega}_H)} = 1, \quad \text{and} \quad \Vert (\mathcal{P}_{\sigma}^{h_n} T - T) x_n \Vert_{H^1_{per}(\tilde{\Omega}_H)} \ge \epsilon_0.
    \end{equation*}
    Let $ y_n = T x_n $, then $ y_n $ forms a precompact set. Without loss of generality, we assume $ \lim\limits_{n \to \infty} y_n = y_0 $. Thus,
    \begin{equation*}
    \epsilon_0 \le (1 + \sup_{h > 0} \Vert \mathcal{P}_{\sigma}^h \Vert) \Vert y_n - y_0 \Vert_{H^1_{per}(\tilde{\Omega}_H)} + \Vert \mathcal{P}_{\sigma}^{h_n} y_0 - y_0 \Vert_{H^1_{per}(\tilde{\Omega}_H)}.
    \end{equation*}
    Letting $ n \to \infty $ leads to a contradiction.
\end{itemize}

\end{appendices}
