\section*{Method}
\subsection*{Boundary point}
To address the hypothesis testing problem formulated in Eq. \ref{eqa:1}, we begin by introducing the notion of boundary points. Specifically, let $Z =\{z_i\}_{i=1}^{m}$ be the pooled sample set by merging \( A = \{x_i\}_{i=1}^{n_A} \) and \( B = \{y_j\}_{j=1}^{n_B} \), where \( m = n_A + n_B \). We define the subset label of a sample $z_{i}$ in $Z$ as:
\begin{equation}
\ell(z_i) =
\begin{cases}
1, & \text{if } z_i \in A, \\
2, & \text{if } z_i \in B.
\end{cases}
\label{eqa:2}
\end{equation}
For each sample $z_i\in Z$, $\mathcal{N}_k(z_i)$ represents the set of its $k$ nearest neighbors in $Z$.

Two samples $z_i$ and $z_j$ are said to be mutual $k$-nearest neighbors if and only if each lies within the other’s set of $k$-nearest neighbors. That is, $z_i \in \mathcal{N}_k(z_j)$ and $z_j \in \mathcal{N}_k(z_i)$. In particular, when $k =1$, we define the boundary point set $\mathcal{B}\subset Z$ as the set of samples in which each sample and its mutual nearest neighbor have different subset labels:
% \begin{equation}
% \begin{aligned}
% \mathcal{B} = \left\{ z_i \in Z \;\middle|\; \exists\, z_j \in Z,\; \mathcal{N}_1(z_i) = z_j , \mathcal{N}_1(z_j) = z_i ,\ell(z_i)\neq \ell(z_j)\right\}.
% \label{eqa:3}
% \end{aligned}
\begin{align}
\mathcal{B} = \{\,z_i \in Z \mid{}&\exists\,z_j \in Z,\;\mathcal{N}_1(z_i)=z_j,\;\mathcal{N}_1(z_j)=z_i,\nonumber\\
&\ell(z_i)\neq \ell(z_j)\,\}.
\end{align}
% \end{equation}

\subsection*{Test statistics and $p$-value calculation} 
% For each boundary point $z_i \in \mathcal{B}$, we use an indicator function $I(\cdot)$ to identify whether the sample and its mutual $k$-nearest neighbor originate from the same source subset.
% \begin{equation}
% I_i(k) =
% \begin{cases}
% 1, & \text{if } z_i \text{ and } \mathcal{N}_k(z_i) \text{ belong to the same subset}, \\
% 0, & \text{otherwise}.
% \end{cases}
% \label{eqa:3}
% \end{equation}
For each boundary point \(z_i \in \mathcal{B}\), the test statistic is defined as follows:
\begin{equation}
T_{i,k} = \sum_{z_{j} \in \mathcal{N}_{k}(z_{i})}
I\bigl(\ell(z_{i}) = \ell(z_{j})\bigr),
\label{eqa:5}
\end{equation}
where $I(\cdot)$ denotes the indicator function. $T_{i,k}$ in Eq. \ref{eqa:5} represents the number of samples in the set of $k$ nearest neighbors of $z_{i}$ whose subset labels are identical to that of $z_{i}$.

Under the null hypothesis that $\pi(A) = \pi(B)$, each neighbor of a boundary point has an equal probability of falling into either subset. Therefore, the test statistic \(T_{i,k}\) follows a binomial distribution:
\begin{equation}
T_{i,k} \sim \mathrm{Bin}(k,0.5).
\label{eqa:6}
\end{equation}

Consequently, the probability of observing at least $t$
neighbors from the same subset can be used as the $p$-value:
\begin{equation}
p_i = \mathbb{P}(T_{i,k} \geq t) = \sum_{r = t}^{k} \binom{k}{r} \left( \frac{1}{2} \right)^k.
\label{eqa:7}
\end{equation}
\subsection*{$P$-value combination}
To assess whether the two subsets belong to the same cluster, we combine the \(p\)-values computed at individual boundary points by applying Fisher’s method \cite{hogg2013introduction}. The combined test statistic is defined as:
\begin{equation}
T_{\text{Fisher}} = -2 \sum_{i=1}^{b} \log(p_i),
\label{eq:fisher}
\end{equation}
where \( b \) is the total number of boundary points.

Under the null hypothesis that all \( p_i \) are independently and uniformly distributed over \([0,1]\), the combined statistic follows a chi-squared distribution with \( 2b \) degrees of freedom:
\begin{equation}
T_{\text{Fisher}} \sim \chi^2(2b).
\label{eq:chisq}
\end{equation}
