        \centering
        \includegraphics[height=2.5in]{images/pointzone.pdf}
        \caption{Illustrating the case where $C^*$ is a regular cell. The red box is $\boxplus_{C^*}$. The two blue vertical lines are vertical point-zone bounding lines; the left one is $\ell^*$. All grey cells are in vertical point-zones  while cells are in vertical gap zones.}
        \label{fig:pointzone}
