\subsection{Statically characterizing the properties and items that are evaluated by a schema}

Our algorithm takes advantage of those situations where one can statically characterize the properties
and the items that a schema evaluates, which happens, for example, for all schemas that do not depend
on an $\qany$ or $\qone$ operator.
%, which is the case for every schema $S_i$ in the DNF schema $\qany: \JArr{S_1,\ldots,S_n}$.
We now formalize this notion.
% by first introducing the notion of \emph{characterizing the property / item evaluation} of a schema $S$, and  the notion of \emph{statically characterized} schema.
%\DC{slightly modified this paragrpha; pls check it }

For example, observe that $S=\qallOf{\qprefIts:[S_1,S_2],\qcont:S_c}$ ``evaluates'' an item $J_i$ at position $i$ of an array $J$ if, and only if,
(1) $J$ satisfies $S$ and  (2) either $i\leq 2$ or $J_i$ satisfies $S_c$. We will express this fact by saying that
``the pair $(2,S_c)$ characterizes the item evaluation of $S$'' (Definition \ref{def:pair}.2 and Definition \ref{def:sta}.4-5-6).
However, if you consider a schema $S=\qanyOf{S_1,S_2}$, where $S_1$ is characterized by $(1,S^1_c)$ and
$S_2$ is characterized by $(2,S^2_c)$, you can only have a lower bound and an upper bound of what is evaluated.
The lower bound is $(1,\qallOf{S^1_c,S^2_c})$: if $\SJudgCJ{S}$,
whichever is the $\qany$ branch that succeeds, if an element has position 1, or if it satisfies $\qallOf{S^1_c,S^2_c}$, then the
element is evaluated.
The upper bound is $(2,\qanyOf{S^1_c,S^2_c})$: if an item of a $J$ such that $\SJudgCJ{S}$ is evaluated by $S$, then
either its position is $\leq 2$ or it satisfies either $S^1_c$ or $S^2_c$. We now formalize all of this.

\begin{definition}[``$k$ matches $\Set{p_1,\ldots,p_n}$'', ``$J$ satisfies $(h,S)$'']\label{def:pair} \ \\
\begin{compactenum}
\item For a set of patterns $P=\Set{p_1,\ldots,p_n}$, we define $\rlan{P}=\bigcup_{i_\in\SetTo{n}}\rlan{p_i}$, and we say that
$k$ matches $P$ when $k\in\rlan{P}$.

\item Given an array $\JArr{J_1,\ldots,J_n}$ we say that the item $J_i$ at position $i$ satisfies the pair $(h,S)$ with
$h\in\Nat$, if either $i \leq h$ or $J_i$ satisfies $S$.
\end{compactenum}
\end{definition}

\begin{definition}[``$\Set{p_1,\ldots,p_n}$/$(h,S)$ is an upper bound/is a lower bound/statically characterizes'']\label{def:sta}\ \\
\begin{compactenum}
\item A set of patterns $\Set{p_1,\ldots,p_n}$ \emph{is an upper bound for property evaluation} of a schema $S$ iff,
for any object $J$, if $J$ satisfies $S$, %$\SJudgCJ{S}\Ret{\btrue}(\btrue,\ps)$,
then every evaluated property matches $\Set{p_1,\ldots,p_n}$.

\item  A set of patterns $\Set{p_1,\ldots,p_n}$ \emph{is a lower bound for property evaluation} of a schema $S$ iff,
for any object $J$,  if $J$ satisfies $S$, then every property of $J$ that matches $\Set{p_1,\ldots,p_n}$
is evaluated.

\item A set of patterns $\Set{p_1,\ldots,p_n}$ \emph{characterizes the property evaluation} of a schema $S$ iff it is both an upper bound and a lower bound.

\item A pair $(h,S')$ \emph{is an upper bound for item evaluation} of a schema $S$ iff,
for any array $J$, if $J$ satisfies $S$, %$\SJudgCJ{S}\Ret{\btrue}(\btrue,\ps)$,
then every item evaluated by $S$ satisfies $(h,S')$.

\item A pair $(h,S')$ \emph{is a lower bound for item evaluation} of a schema $S$ iff,
for any array $J$, if $J$ satisfies $S$, %$\SJudgCJ{S}\Ret{\btrue}(\btrue,\ps)$,
then every item of $J$ that satisfies $(h,S')$ is evaluated by $S$.

\item A pair $(h,S')$ \emph{characterizes the item evaluation} of a schema $S$ iff it is both an upper bound and a lower 
bound.

\item A schema $S$ is \emph{statically characterized} iff there exist $\Set{p_1,\ldots,p_n}$ that \emph{characterizes its property evaluation}  and a pair $(h,S')$ that \emph{characterizes its item evaluation}.

\end{compactenum}

%The \emph{upper/lower bound for property evaluation} of a keyword $K$ is defined by substituting ``schema $S$'' with ``keyword $K$''
%in the above definition,
%and the same holds for the other terms defined here.
\end{definition}

