%For any keyword $K$, $\MinEIK{K}$ is a lower bound for the item evaluation of schema $\JObj{K}$, 
%and $\MaxEIK{K}$ is an upper bound for the same schema.
%
\end{propxrep}

\begin{proof}
%\begin{proofsketch}
%Verified 16/12/2024
We prove, by induction, what follows.
For any schema $S$, $\MinEP(S)$ is a lower bound for its property evaluation, and $\MaxEP(S)$ is an upper bound.
For any schema $S$, $\MinEI(S)$ is a lower bound for its item evaluation, and $\MaxEI(S)$ is an upper bound.
For any keyword $K$, $\MinEPK{K}$ is a lower bound for the property evaluation of schema $\JObj{K}$, 
and $\MaxEPK{K}$ is an upper bound for the same schema.
For any keyword $K$, $\MinEIK{K}$ is a lower bound for the item evaluation of schema $\JObj{K}$, 
and $\MaxEIK{K}$ is an upper bound for the same schema.

We start with $\MinEP$ and $\MaxEP$.

Cases ${\qprops}$ and ${\qpattProps}$ are trivial.\ 
Cases {\qunProps} is trivial as well -  a successful schema $\JObj{\qunProps}$ evaluates
all properties. Of course, when $\qunProps$ is not the only keyword it does not evaluate all properties
but only those that are not evaluated by the other properties, but we deal with this aspect in the inductive
proof for case $\JObj{K_1,\ldots,K_n}$. The same holds for $\qaddProps$.

Case $\qdref:u$ is trivial.

$\MinEP(\JObj{K_1,\ldots,K_n})=\bigcup_{i\in \SetTo{n}}{\MinEPK{K_i}}$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{K_1,\ldots,K_n}$, then every property of $J$ that matches 
${\bigcup_{i\in \SetTo{n}}{\MinEPK{K_i}}}$ is evaluated.
If a property $p$
matches ${\bigcup_{i\in \SetTo{n}}{\MinEPK{K_i}}}$, then it matches $\MinEPK{K_l}$ for some $l$.
Since $\JObj{K_1,\ldots,K_n}$ is satisfied, then we know that $K_l$ is satisfied,
hence, by induction, property $p$ is evaluated by the schema $\JObj{K_l}$.
If $K_l$ is an independent keyword, we conclude that $p$ is evaluated by the keyword $K_l$, hence 
is evaluated by the schema.
If $K_l$ is either $\qunProps$ or $\qaddProps$, then we know that $p$ is either evaluated by $K_l$ or by a keyword that precedes $K_l$,
hence it is evaluated by the schema.

$\MaxEP(\JObj{K_1,\ldots,K_n})=\bigcup_{i\in \SetTo{n}}{\MaxEPK{K_i}}$:
We want to prove that 
for any object $J$,  if a property $p$ of $J$ is evaluated by $\JObj{K_1,\ldots,K_n}$, then $p$ matches 
${\bigcup_{i\in \SetTo{n}}{\MaxEPK{K_i}}}$.
If $p$ is evaluated by $\JObj{K_1,\ldots,K_n}$ then $p$ is evaluated by at least
one keyword $K_l$; if $K_l$ is an independent property, then $p$ is also evaluated by
$\JObj{K_l}$, hence, by induction, $p$ is in $\MaxEPK{K_l}$, hence it is in ${\bigcup_{i\in \SetTo{n}}{\MaxEPK{K_i}}}$.
If $K_l$ is $\qunProps:S$, then it is possible that $p$ is not evaluated by $\JObj{K_l}$ since $p$ may be
evaluated by a keyword that precedes $K_l$, but still $p$ is in ${\bigcup_{i\in \SetTo{n}}{\MaxEPK{K_i}}}$
since $\MaxEPK{K_l}=\qkw{.*}$, and $\qkw{.*}$ matches any property. The same proof holds for
$\qaddProps:S$.

$\MinEP(\qone: \JArr{S_1,\ldots,S_n}) = \bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{(\qone: \JArr{S_1,\ldots,S_n})}$, then every property of $J$ that matches 
$\bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$ is evaluated.
Assume that  $J$ satisfies $\JObj{(\qone: \JArr{S_1,\ldots,S_n})}$. Then, $J$ satisfies $S_l$ for some $l$, hence,
by induction, every property of $J$ that matches $\MinEP(S_l)$ is evaluated.
If a property of $J$  matches $\bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$, then it matches $\MinEP(S_l)$,
and the thesis follows.

$\MaxEP(\qone: \JArr{S_1,\ldots,S_n}) = \bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}$:
We want to prove that 
for any object $J$,  if a property $p$ of $J$ is evaluated by $\qone: \JArr{S_1,\ldots,S_n}$, then $p$ matches 
${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.
If a property $p$ of $J$ is evaluated by a successful $\qone: \JArr{S_1,\ldots,S_n}$, then it is evaluated by the only
branch of $\qone$ that succeeds; let us call it $S_l$. 
By induction, property $p$ matches $\MaxEP(S_l)$, hence it matches ${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.

$\MinEP(\qany: \JArr{S_1,\ldots,S_n}) = \bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{(\qany: \JArr{S_1,\ldots,S_n})}$, then every property of $J$ that matches 
$\bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$ is evaluated.
Assume that  $J$ satisfies $\JObj{(\qany: \JArr{S_1,\ldots,S_n})}$. Then, $J$ satisfies $S_l$ for some $l$, hence,
by induction, every property of $J$ that matches $\MinEP(S_l)$ is evaluated.
If a property of $J$  matches $\bigcap_{i\in \SetTo{n}}{\MinEP(S_i)}$, then it matches $\MinEP(S_l)$,
and the thesis follows.

$\MaxEP(\qany: \JArr{S_1,\ldots,S_n}) = \bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}$:
We want to prove that 
for any object $J$,  if a property $p$ of $J$ is evaluated by $\qany: \JArr{S_1,\ldots,S_n}$, then $p$ matches 
${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.
If a property $p$ of $J$ is evaluated by a successful $\qany: \JArr{S_1,\ldots,S_n}$, then it is evaluated by some
branches of $\qany$ that succeed; let us consider anyone of them, and call it $S_l$. 
By induction, property $p$ matches $\MaxEP(S_l)$, hence it matches ${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.

$\MinEP(\qall: \JArr{S_1,\ldots,S_n}) = \bigcup_{i\in \SetTo{n}}{\MinEP(S_i)}$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{(\qall: \JArr{S_1,\ldots,S_n})}$, then every property of $J$ that matches 
$\bigcup_{i\in \SetTo{n}}{\MinEP(S_i)}$ is evaluated.
Assume that  $J$ satisfies $\JObj{(\qall: \JArr{S_1,\ldots,S_n})}$. Then, $J$ satisfies every $S_l$ hence,
by induction, every property of $J$ that matches $\MinEP(S_l)$ is evaluated, for each $l$,
hence every property in $\bigcup_{i\in \SetTo{n}}{\MinEP(S_i)}$ is evaluated.

$\MaxEP(\qall: \JArr{S_1,\ldots,S_n}) = \bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}$:
We want to prove that 
for any object $J$,  if a property $p$ of $J$ is evaluated by $\qall: \JArr{S_1,\ldots,S_n}$, then $p$ matches 
${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.
If a property $p$ of $J$ is evaluated by $\qall: \JArr{S_1,\ldots,S_n}$, then it is evaluated by some $S_l$. 
By induction, property $p$ matches $\MaxEP(S_l)$, hence it matches ${\bigcup_{i\in \SetTo{n}}{\MaxEP(S_i)}}$.

Any other keyword is either a structural keyword different from the ones listed above or is the $\qnot$ keyword.
The structural keywords different from the ones listed above do not evaluate any property of the instance under validation.
A successful $\qnot:S$ keyword is applied to a schema $S$ that does not validate the instance, and a schema that does not
validate an instance does not return any validated property.
Schemas {\xtrue} and {\xfalse} do not evaluate any properties.

We move to $\MinEI$ and $\MaxEI$.

We say that an item $J_i$ of an array 
$J=\JArr{J_1,\ldots,J_n}$, satisfies the first component of a pair $(l,S)$, if $i\leq l$, and that is satisfies
the second component if $J_i$ satisfies $S$.
We say that $J_i$ satisfies the pair $(l,S)$ if it satisfies either the first or the second component.


$\MinEI/\MaxEIK{\qits:S}=(\Inf,\xtrue)$: a schema $\JObj{ \qits: S}$ evaluates all items of any evaluated array,
and every item of an array satisfies the pair $(\Inf,\xtrue)$.

$\MinEI/\MaxEIK{\qprefIts:\JArr{S_1,\ldots,S_n}}=(n,\xtrue)$: a schema $\JObj{ \qprefIts:\JArr{S_1,\ldots,S_n}}$ 
evaluates all and only the items with position $\leq n$, which are exactly the items that satisfy $(n,\xfalse)$.

$\MinEI/\MaxEIK{\qcont: S}=(0,S)$: a schema $\JObj{ \qcont: S}$ 
evaluates all and only the items that satisfy $S$, which are exactly the items that satisfy $(0,S)$.

All other cases are analogous to those for $\MinEP/\MaxEP$, where $\min$ on the first component and
$\qall$ on the second one take the place of $\bigcap$, and $\max$ on the first component and
$\qany$ on the second one take the place of $\bigcup$.
We report a couple of cases as examples.

$\MinEI(\JObj{K_1,\ldots,K_n})=(\max_{i\in \SetTo{n}}(h_i), \JObj{\qany : [S'_1,\ldots,S'_n]})$
where $(h_i,S'_i)=\MinEI(S_i)$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{K_1,\ldots,K_n}$, then every item of $J$ that satisfies the pair 
$\MinEI(\JObj{K_1,\ldots,K_n})$ is evaluated.
If an item $J_i$ satisfies the pair, then either its position is less than $\max_{i\in \SetTo{n}}(h_i)$,
or it satisfies $\JObj{\qany : [S'_1,\ldots,S'_n]}$.
In the first case, its position is less then $h_l$ for some $l$; in the second case, it satisfies $S'_l$ for some $l$;
hence, in both cases, $J_i$ satisfies a pair $(h_l,S'_l)$ for some $l$.
Since $(h_l,S'_l)=\MinEIK{K_l}$,
then, by induction, item $J_i$ is evaluated by the schema $\JObj{K_l}$.
If $K_l$ is an independent keyword, we conclude that $J_i$ is evaluated by the keyword $K_l$, hence 
is evaluated by the schema.
If $K_l$ is either $\qits$ or $\qunIts$, then we know that $J_i$ is either evaluated by $K_l$ or by a keyword that precedes $K_l$,
hence it is evaluated by the schema.

$\MaxEI(\JObj{K_1,\ldots,K_n})=(\max_{i\in \SetTo{n}}(h_i), \JObj{\qany : [S'_1,\ldots,S'_n]})$
where $(h_i,S'_i)=\MaxEI(S_i)$:
We want to prove that 
for any object $J$,  if an item $J_i$ of $J$ is evaluated by $\JObj{K_1,\ldots,K_n}$, then $J_i$ satisfies the pair 
$\MaxEI(\JObj{K_1,\ldots,K_n})$.
If $J_i$ is evaluated by $\JObj{K_1,\ldots,K_n}$ then $J_i$ is evaluated by at least
one keyword $K_l$. If $K_l$ is an independent item, then $J_i$ is also evaluated by
$\JObj{K_l}$, hence, by induction, $J_i$ satisfies $\MaxEIK{K_l}=(h_l,S'_l)$, hence, either its position is
less then $h_l$, or it satisfies $S'_l$. In the first case its position is less then $\max_{i\in \SetTo{n}}(h_i)$,
in the second case it satisfies $ \JObj{\qany : [S'_1,\ldots,S'_n]}$, hence it satisfies the pair.
If $K_l$ is $\qunProps:S$, then it is possible that $J_i$ is not evaluated by $\JObj{K_l}$ since $J_i$ may be
evaluated by a keyword that precedes $K_l$, but still $J_i$ satisfies $ \JObj{\qany : [S'_1,\ldots,S'_n]}$
since $\MaxEIK{K_l}=(\Inf,\xtrue)$, hence $S'_l=\xtrue$ (a second reason why $J_i$ satisfies the pair
is that  $h_l=\Inf$ hence the position of $J_i$ satisfies  $\max_{i\in \SetTo{n}}(h_i)$).
The same reasoning holds when $K_l$ is $\qits:S$.

$\MinEI(\qone: \JArr{S_1,\ldots,S_n}) =(\min_{i\in \SetTo{n}}(h_i), \JObj{\qall : [S'_1,\ldots,S'_n]})$
where $(h_i,S'_i)=\MinEI(S_i)$:
We want to prove that 
for any object $J$,  if $J$ satisfies $\JObj{(\qone: \JArr{S_1,\ldots,S_n})}$, then every item $J_i$
of $J$ that satisfies 
the pair $\MinEI(\qone: \JArr{S_1,\ldots,S_n})$ is evaluated.
If an item $J_i$ satisfies the pair, then either its position is less than $\min_{i\in \SetTo{n}}(h_i)$,
or it satisfies $\JObj{\qall : [S'_1,\ldots,S'_n]}$.
In the first case, its position is less then $h_l$ for every $l$; in the second case, it satisfies $S'_l$ for every $l$;
hence, in both cases, $J_i$ satisfies every pair $(h_l,S'_l)$, that is, it satisfies $\MinEI(S_l)$ for every $l$.
Since  $J$ satisfies $\JObj{(\qone: \JArr{S_1,\ldots,S_n})}$, then, $J$ satisfies $S_o$ for some $o$, hence,
by induction, every item of $J$ that satisfies $\MinEI(S_o)$ is evaluated, and we have just proved that $J_i$
satisfies every pair  $\MinEI(S_l)$, including  $\MinEI(S_o)$, hence $J_i$ is evaluated.

$\MaxEI(\qone: \JArr{S_1,\ldots,S_n}) =(\max_{i\in \SetTo{n}}(h_i), \JObj{\qany : [S'_1,\ldots,S'_n]})$
where $(h_i,S'_i)=\MaxEI(S_i)$:
We want to prove that 
for any object $J$,  if an item $J_i$ of $J$ is evaluated by $\qone: \JArr{S_1,\ldots,S_n}$, then $J_i$ satisfies the pair
$\MaxEI(\qone: \JArr{S_1,\ldots,S_n}) $.
If an item $J_i$ of $J$ is evaluated by a successful $\qone: \JArr{S_1,\ldots,S_n}$, then it is evaluated by the only
branch of $\qone$ that succeeds; let us call it $S_o$. 
By induction, item $J_i$ satisfies $\MaxEI(S_o)$, hence it either has a position that is smaller than $h_o$
or it satisfies $S'_o$. In the first case it satisfies the first component $\max_{i\in \SetTo{n}}(h_i)$,
in the second case it satisfies the second component $\JObj{\qany : [S'_1,\ldots,S'_n]}$.

