\hide{
The property specifies that $\MinEP(S)$ is a lower bound, but not that it is the best possible 
lower bound; for example, if a branch $S_i$ of $\qanyOf{S_1,\ldots,S_n}$ were unsatisfiable, we could exclude
that branch from the computation, and obtain, in general, a greater, hence more precise, lower bound,
and the same holds for the other three functions.
Our algorithm uses four functions for some crucial optimizations; stricter bounds produce more
effective optimizations, but there is a cost-efficacy trade-off.
Property~\ref{pro:minmax} ensures that our specific definition is sound, and our experiments are reassuring about the
cost-efficacy trade-off, but all the theory that we develop would still work with a different definition of this
function, provided it satisfies the soundness property.
}%END HIDE


When $\MinEP(S)$ and $\MaxEP(S)$ denote the same language, then
$\MinEP(S)$ (or, equivalently, $\MaxEP(S)$) statically characterizes the property evaluation of $S$,
and our algorithm can use this fact to produce an optimized (smaller) encoding
(as we will see in Section \ref{sec:computing}). %, Definition \ref{def:funENF}).
However, deciding whether
$\MinEP(S)$ and $\MaxEP(S)$ are equivalent is computationally expensive, and therefore
different implementations can devote a different effort to this optimization.
In order to express this fact, we define a function $\ExEP_{eq}(S)$,
which is parametrized on the function $eq$ that is used to compare two sets of patterns,
so that  $\ExEP_{eq}(S)=\Set{p_1,\ldots,p_n}$ when 
$eq$ is able to prove that $\MinEP(S)$ and $\MaxEP(S)$ are both equivalent to some
$\Set{p_1,\ldots,p_n}$, and $\ExEP_{eq}(S)=\uparrow$ otherwise.
Parametrizing $\ExEP_{eq}$ over $eq$ allows us to discuss the effect of different choices for function~$eq$.


\begin{definition}[$\ExEP_{eq}(S)$, $\ExEI_{eq}(S)$, $\ExEP_{eq}(S)\Down/\Up$, $\ExEI_{eq}(S)\Down/\Up$]\label{def:eq}
Assume that $\key{eq}$ is a binary relation such that 
$$
\begin{array}{lllllllllllllll}
eq(\Set{p_1,\ldots,p_n},\Set{p'_1,\ldots,p'_m}) &\Implies& \rlan{\Set{p_1,\ldots,p_n}}=\rlan{\Set{p'_1,\ldots,p'_m}}\\[\NL]
eq((n,S),(m,S')) &\Implies& (n=m) \And (\forall J.\  (J \text{ satisfies } S) \Iff (J \text{ satisfies } S'))
\end{array}
$$
The functions $\ExEP_{eq}(S)$ and  $\ExEI_{eq}(S)$ are defined as follows.
$$
\begin{array}{rlllllllllllllll}
\Not eq(\MinEP(S),\MaxEP(S))   &\Implies& \ExEP_{eq}(S)&=&\uparrow   & &   \\[\NL]
 eq(\MinEP(S),\MaxEP(S))   &\Implies& \ExEP_{eq}(S)&=&\MinEP(S)   & &   \\[\NL]
\Not eq(\MinEI(S),\MaxEI(S))   &\Implies& \ExEI_{eq}(S)&=&\uparrow   & &   \\[\NL]
 eq(\MinEI(S),\MaxEI(S))   &\Implies& \ExEI_{eq}(S)&=&\MinEI(S)   & &   
\end{array}
$$
%The functions $\ExEP_{eq}(K)$, $\ExEI_{eq}(K)$ are defined in the same way.
We use $\ExEP_{eq}(S)\Down$ to indicate that $\ExEP_{eq}(S)\neq\,\uparrow$,
and similarly for $\ExEI_{eq}(S)\Down$.
We use $\ExEP_{eq}(S)\Up$ to indicate that $\ExEP_{eq}(S)=\uparrow$,
and similarly for $\ExEI_{eq}(S)\Up$.
\end{definition}

For any $eq$ that enjoys the properties of Definition \ref{def:eq}, the following property holds.

\begin{propxrep}[$\ExEP_{eq}(S)$, $\ExEI_{eq}(S)$, characterize property/item evaluation]\label{pro:ex}
For any schema $S$, if $\ExEP_{eq}(S)\Down$, then $\ExEP_{eq}(S)$ characterizes the property evaluation of $S$.
For any schema $S$, if $\ExEI_{eq}(S)\Down$, then $\ExEI_{eq}(S)$ characterizes the item evaluation of $S$.
%The same properties hold for a keyword $K$.
\end{propxrep}

From now on, we assume that the function $eq$ is fixed and that it includes at least syntactical equality, so that
$eq(P,P)$ and $eq((n,S),(n,S))$ hold.

%Let us say that a keyword $K$ has a positive connection to $K'$ if $K=\qany/\qall/\qone : [S_1,\ldots,S_n]$
%or $K=\qdref : x$ with $E(x)=S_1$, and $K'$ is a top-level keyword of one of those 
%$S_i$'s. Let us say that $K'$  is {\AAF} $K$ if there exists a path (maybe of length 0) of 
%positive connections between $K$ and $K'$.
\begin{example}
Consider the following schema.
%
\begin{Verbatim}[fontsize=\small,frame=lines]
{ "anyOf": [ 
    { "properties": { "a": { "type":"string" } }, "additionalProperties":false },
    { "properties": { "b": { "type":"string" } }, "additionalProperties":false }
  ]
}
\end{Verbatim}

\newcommand{\KeyKey}[1]{\qkw{\PPP{#1}}}
The first branch $S_1$ of $\qany$ has $\MinEP(S_1)=\MaxEP(S_1)=\ExEP_{eq}(S_1)=\Set{\KeyKey{a},\qkw{.*}}$;
the second branch $S_2$ has $\MinEP(S_1)=\MaxEP(S_1)=\ExEP_{eq}(S_1)=\Set{\KeyKey{b},\qkw{.*}}$.
Our algorithm may rewrite both of them as just $\Set{\qkw{.*}}$, but let us assume it does not.
Then, we have $\MinEP(\qany:[S_1,S_2])=\Set{\KeyKey{a},\qkw{.*}}\cap\Set{\KeyKey{b},\qkw{.*}}=\Set{\qkw{.*}}$,
and $\MaxEP(\qany:[S_1,S_2])=\Set{\KeyKey{a},\qkw{.*}}\cup\Set{\KeyKey{b},\qkw{.*}}=\Set{\KeyKey{a},\KeyKey{b},\qkw{.*}}$.

Now, the value of $\ExEP_{eq}(\qany:[S_1,S_2])$ depends on the function $eq$.
If $eq$ is just set equality, that we indicate as $=$, then we have that $\neg eq(\MinEP(\qany:[\ldots]),\MaxEP(\qany:[\ldots]))$,
hence $\ExEP_{=}(\qany:[S_1,S_2])\Up$.
The function $eq$ that we have implemented, however, regards any two sets that contain $\qkw{.*}$ as equivalent, ignoring any other pattern
in this case; let us call this function $eq^{+}$; in this case, $\ExEP_{eq^{+}}(\qany:[S_1,S_2])=\Set{\qkw{.*}}$.
\end{example}

We now show that $\ExEP_{eq}(S)$ is undefined only when $S$ depends on either an $\qany$ or a $\qone$ keyword.
We first define the notion of \emph{\AAF}.

\begin{definition}[$K$ {\AAF}  $K'$]
For a fixed schema $S$, we say an occurrence of a subkeyword $K$ is {\AAF} an occurrence a subkeyword $K'$ if there is a path
from $K$ to $K'$ that only crosses boolean keywords or references.
Formally,  $K$ is immediately {\AAF} $K'$ if either (1) $K$ is a boolean keyword $\qall/\qany/\qone:[S_1,\ldots,S_k]$, and
$K'$ is a top-level keyword in one of the $S_i$ arguments of $K$, or (2) $K$ is a reference keyword $\qdref: u$, and
$K'$ is a top-level keyword in $\key{deref}(u)$.
 $K$ is {\AAF} $K'$ if there exists a sequence $K_1,\ldots,K_n$ of keyword occurrences such that either $n=1$, or,
 for each $i\in\SetTo{n-1}$, $K$ is immediately {\AAF} $K'$.
 An occurrence of a subschema $S'$ of $S$ is {\AAF} $K'$ if one of the top-level keywords of $S'$ is {\AAF}
  $K'$.
\end{definition}

The following property implies that  $\ExEP_{eq}(S)$ is always well defined unless $S$ is {\AAF}
an $\qany$ keyword or a $\qone$ keyword that evaluates different properties in its different branches,
and similarly for  $\ExEI_{eq}$.


\begin{propxrep}[ $\ExEP_{eq}$,  $\ExEI_{eq}$, and $\qany$/$\qone$]\label{pro:sta}
% $\ExEP_{eq}{\JObj{K}}\Down$ holds for any keyword $K$ which is not {\AAF}
%any $\qany$ or $\qone$
%keyword $K'$ such that $\MinEPK(K')\neq\MaxEPK(K')$.
$\MinEP(S)=\MaxEP(S)$ holds  for any schema $S$ which is not {\AAF}
any $\qany$ or $\qone$
keyword $K'$ such that $\MinEP(\JObj{K'})\neq\MaxEP(\JObj{K'})$.
The same property holds if we substitute $\MinEP/\MaxEP$ with $\MinEI/\MaxEI$.
\end{propxrep}

