\item \label{andor:v} $\qany: L' \LC L'' \LC \LClose(L',L'') $ is equivalent to $\qany: L' \LC L''  $;
\item \label{andor:vi} $\qany : \LOr(L_1,\ldots,L_n)$ is equivalent to $\qany : [ \JObj{\qany: L_1},\ldots,\JObj{\qany: L_n}]$;
\item \label{andor:vii} If each list $L_i$ is cover-closed and is {\ESC}, and, for any $i\neq j$, $\JObj{\qany:{L_i}}$ and $\JObj{\qany:{L_j}}$ 
    are disjoint, then $L_1 \LC \ldots \LC L_n$ is cover-closed and is {\ESC}.
\end{compactenum}
\end{propxrep}

