\section{Proposed Method}
The proposed TriniMark differs from post-hoc watermarking and model watermarking approaches. Instead of embedding watermarks into the generated speech or the model parameters, we leverage watermark transfer learning to learn from watermarked training data, thereby generating watermarked speech via DMs, as depiected in Fig.~\ref{fig_pipe}. 
The entire generative watermarking consists of two stages. The first stage is pre-training the watermark encoder and decoder. The second stage involves fine-tuning the diffusion models utilizing the pretrained encoder and decoder with watermark priors. The detailed process will be described in the following sections.


%----------------------------------------------------------------------
\subsection{Pre-training Watermark Encoder and Decoder}
\subsubsection{Architecture of Watermark Encoder and Decoder}
We meticulously design a structure-lightweight watermark encoder $\mathcal{E}(\cdot)$ and a decoder $\mathcal{D}(\cdot)$ to learn watermark priors, as illustrated in Fig.~\ref{fig_wm}, ensuring its transferability to the diffusion model.
\textit{The watermark encoder} consists of a DenseBlock (DB) and a structure-lightweight Speech Reconstruction Network (SRNet). 
The DB includes two fully connected (FC) layers and a ReLU activation. 
The SRNet contains a downsampling block and an upsampling block. The downsampling block consists of four 1D convolutional layers, while the upsampling block comprises four 1D convolutional layers and four 1D transposed convolutional layers. 
The lightweight structure of the SRNet is attributed to the exclusion of all activation functions and normalization operations, comprising only convolutional layers. This design choice is motivated by the fact that, unlike frequency domain transformation, which relies on high-dimensional features for reconstruction, SRNet utilizes only the time-domain features of speech. As described in MobileNetV2~\cite{sandler2018mobilenetv2}, activation functions such as ReLU can cause excessive loss of low-dimensional features. Consequently, this lightweight structure is employed to reconstruct watermarked speech while preserving its essential characteristics, which can also accelerate training speed and reduce inference latency.

\textit{The watermark decoder} comprises a ConvBlock and a DenseBlock. The ConvBlock is made up of seven deliberated designed Temporal-aware Gated Convolutional Networks (TGCNs), which are redesigned Gated Convolutional Networks~\cite{dauphin2017gated_cnn} specifically tailored for the temporal features of speech. Each TGCN has two branches: one branch only has a single 1D convolutional layer, while the other branch first passes through a 1D convolutional layer, followed by batch normalization, and finally a gating mechanism with a Sigmoid function. The outputs of the two branches are then combined using the Hadamard product. Utilizing TGCNs allows the decoder to capture high-dimensional time-domain features of speech, enabling more precise watermark recovery.
For robustness, we introduced a noise layer $\mathbf{N}(\cdot)$ that includes common post-processing operations for speech.

%----------------------------------------------------------------------
\subsubsection{Pipeline of Pre-training}
The cover speech $\mathbf{s} \in \mathbb{R}^{\mathbf{u}}$ and the watermark $\mathbf{w} \in \{0, 1\}^{l}$ as the input for the encoder $\mathcal{E}(\cdot)$, where $\mathbf{u}=C \times L$, $C$ represents channels, $L$ denotes the length of speech, and $l$ is the length of watermark.
The watermark $\mathbf{w}$ is first transformed by a DenseBlock containing two fully connected (FC) layers. Then it is concatenated with the speech to reconstruct the watermarked speech $\hat{\mathbf{s}}$.
Before extraction, the watermarked speech undergoes a noise layer $\mathbf{N}(\cdot)$ to enhance the resilience of the decoder against various attacks. Finally, the decoder $\mathcal{D}(\cdot)$ processes the attacked speech to disentangle the watermark features and then recover the watermark $\hat{\mathbf{w}}$. The overall pipeline can be formatted as:
\begin{equation}
    \hat{\mathbf{w}} = \mathcal{D}(\mathbf{N}(\mathcal{E}(\mathbf{s}, \mathbf{w}))).
\end{equation}

%----------------------------------------------------------------------
\subsubsection{Jointly Optimizing Watermark Encoder and Decoder}
\label{sec_jointo}
Pre-training the watermark encoder-decoder aims to enable the decoder to acquire the watermark priors. Therefore, we employ a joint optimization strategy for training. For recovery accuracy, we employ binary cross-entropy (BCE) for constrain:
\begin{equation}
\label{eq_wm}
    \mathcal{L}_{W} = - \sum_{i=1}^{k} w_i \log {\hat{w}_i} + (1-w_i) \log(1-\hat{w}_i).
\end{equation}

Regarding the quality of watermarked speech, we first utilize the mel-spectrogram loss $\mathcal{L}_{Mel}$ to constrain the distance between the cover speech $\mathbf{s}$ and the watermarked speech $\hat{\mathbf{s}}$.
\begin{equation}
    \mathcal{L}_{Mel} = \mathbb{E}_{\mathbf{s}, \hat{\mathbf{s}}} \big[ || \phi(\mathbf{s}), \phi(\hat{\mathbf{s}}) ||_1 \big],
\end{equation}
where $\phi(\cdot)$ represents the transformation of mel-spectrograms and $||\cdot||$ denotes the $L_1$ norm. Furthermore, we employ the logarithmic STFT magnitude loss $\mathcal{L}_{Mag}$ for optimization. 
\begin{equation}
    \mathcal{L}_{Mag} = || \log(\mathbf{STFT}(\mathbf{s})), \log(\mathbf{STFT}(\hat{\mathbf{s}})) ||_1,
\end{equation}
where $\mathbf{STFT}(\cdot)$ denotes transformation of STFT magnitude.

The entire loss of pre-training can be defined as:
\begin{equation}
    \mathcal{L}_{Pre} = \gamma_{mel} \mathcal{L}_{Mel} + \gamma_{mag} \mathcal{L}_{Mag} + \gamma_{w} \mathcal{L}_{W},
\end{equation}
where $\gamma_{mel}$, $\gamma_{mag}$, $\gamma_{w}$ are the hyper-parameters, respectively, to balance the speech quality and extraction accuracy.


%----------------------------------------------------------------------
\subsection{Fine-tuning the Diffusion Models}
\subsubsection{Fine-tuning Strategy}
The conventional objective of training the diffusion models is to constrain the noise $\epsilon$ added during the diffusion process and the noise estimated by the prediction network $\epsilon_\theta(\cdot)$, as described by Eq.~\ref{eq_train}. 
However, this fine-tuning method by constraining noise significantly affects the ability of diffusion models to learn the watermark. As a result, the watermark constraint loss struggles to converge during the fine-tuning process.
Moreover, this approach could impair the generative capability of diffusion models, leading to a decline in speech quality.

Considering the above issues, we propose a novel waveform-guided fine-tuning method (WGFT) that constrains the training speech $\mathbf{s}_0$ and the watermarked speech $\hat{\mathbf{s}}_0^{wm}$ obtained through the complete sampling process rather than constraining the original noise and predicted noise, ensuring the generative capability of diffusion models.
The rationale behind this design is that the diffusion model has already learned the prior knowledge of noise prediction during its pre-training process. Consequently, the focus should shift towards enabling the diffusion model to learn the watermark through transferability during the fine-tuning stage.
Furthermore, we constrain the training speech $\mathbf{s}_0$ and watermarked speech $\hat{\mathbf{s}}_0^{wm}$ using the mel-spectrogram loss $\mathcal{L}_{Mel}$ and the log STFT magnitude loss $\mathcal{L}_{Mag}$, as designed in Section~\ref{sec_jointo} to ensure the generative capability of the diffusion model is not significantly impacted after fine-tuning.
The corporate loss $\mathcal{L}_{Speech}$ for speech quality can be computed as follows:
\begin{equation}
    \mathcal{L}_{Speech} = \psi_{mel} \mathcal{L}_{Mel} + \psi_{mag} \mathcal{L}_{Mag},
\end{equation}
where $\psi_{mel}$ and $\psi_{mag}$ are hyper-parameters for balancing two loss terms, respectively. For watermark recovery accuracy, the BCE loss in Eq.~\ref{eq_wm} is continued as the constraint. 

In a nutshell, the final loss for fine-tuning is defined as:
\begin{equation}
    \mathcal{L}_{FT} = \lambda_{speech} \mathcal{L}_{Speech} + \lambda_{w} \mathcal{L}_W,
\end{equation}
where $\lambda_{spe}$ and $\lambda_{w}$ are hyper-parameters for the trade-off between the speech quality and extraction accuracy, respectively.

%----ALgorithm-----------------------------------------------------------------
\newcommand{\lIfElse}[3]{\lIf{#1}{#2 \textbf{else}~#3}}
\begin{algorithm}[t]
\caption{Waveform-Guided Fine-tuning Strategy.}
\label{algo}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
% \SetKwRepeat{Repeat}{repeat}{until}

\KwIn{Training speech $\mathcal{D}_{train}$, pretrained watermark encoder $\mathcal{E}(\cdot)$ and decoder $\mathcal{D}(\cdot)$, flexible watermark $\mathbf{w}$, hyper-parameter $\alpha_t$, and diffusion step $T$.}


\Repeat{converged}{
$\mathbf{s}_0 \leftarrow \mathbf{s}_0 \sim q_{data}(\mathbf s_0)$;

$\hat{\mathbf{s}}_0 \leftarrow \hat{\mathbf{s}}_0 = \mathcal{E}(\mathbf{s}_0, \mathbf{w})$; \Comment $\mathbf{w} \in \{0, 1\}^l$

% $\epsilon \leftarrow \epsilon \sim \mathcal{N}(0, \mathbf{I})$;

% $\hat{\mathbf{s}}_T^{wm} \leftarrow \hat{\mathbf{s}}_T^{wm} = \sqrt{\overline{\alpha}_t} \hat{\mathbf{s}}_0 + \sqrt{1-\overline{\alpha}_t} \mathbf{\epsilon}$;
$\mathbf{s}_T \leftarrow \mathbf{s}_T \sim \mathcal{N}(0, \mathbf{I})$;

% $t \leftarrow t \sim \mathbf{Uniform}(\{1, ..., T\})$;

\For{$t \leftarrow T, ..., 1$}  
{
    \lIfElse{$t > 1$}{$\mathbf{z} \sim \mathcal{N}(0, \mathbf{I})$}{$\mathbf{z} \leftarrow 0$}

    $\hat{\mathbf{s}}_{t-1}^{wm} \leftarrow \frac{1}{\sqrt{\alpha_t}} \big(\hat{\mathbf{s}}_t^{wm} - \frac{1-\alpha_t}{\sqrt{1-\overline \alpha_t}} \mathbf{\epsilon}_\theta(\hat{\mathbf{s}}_t^{wm}, t, c) \big) + \delta_t \mathbf z$\;

    \lIf{$t = 3$ \\}{$\hat{\mathbf{s}}_3^{wm} \leftarrow \hat{\mathbf{s}}_3^{wm} \otimes \hat{\mathbf{s}}_0$}
}

\Return $\hat{\mathbf{s}}_0^{wm}$;

$\hat{\mathbf{w}} \leftarrow \hat{\mathbf{w}} = \mathcal{D}(\hat{\mathbf{s}}_0^{wm})$;

Take gradient descent step on:
$\nabla_\theta(|| \phi(\mathbf{s}_0), \phi(\hat{\mathbf{s}}_0^{wm}) ||_1) + || \log(\mathbf{STFT}(\mathbf{s}_0)), \log(\mathbf{STFT}(\hat{\mathbf{s}}_0^{wm})) ||_1) - \sum_{i=1}^{k} w_i \log {\hat{w}_i} + (1-w_i) \log(1-\hat{w}_i) $;
}
%\BlankLine
\end{algorithm}

