Now, we can prove the following theorem. 

\begin{theorem} \label{th:pat-pl}
	For every graph $G$,  
    %$\dpr(G)\le \pl(G)$,  
    $\rho(G)\le 2\cdot\dsp(G)+1$, 
    %$\Delta(G)\le 4\cdot\dsp(G)+1$, 
    $\dsp(G)\le  \dpr(G)\le 3\cdot\dsp(G)$, and 
$$\dsp(G)\leq \dpr(G)\le \pl(G)\le 4\cdot\dsp(G)\le 4\cdot\dpr(G),$$ 
$$\dsp(G)\leq \dpr(G)\le \Delta(G)\le 4\cdot\dsp(G)+1\le 4\cdot\dpr(G)+1,$$    
$$\frac{\adc(G)-2}{2}\leq \dsp(G)\leq \dpr(G)\le  2\cdot\adc(G)+1,$$  
$$\frac{\adc(G)}{2}\leq  \pat(G)\le \pcc(G)\le 3\cdot\adc(G)+2,$$ 
$$\frac{\pl(G)}{2}\leq \pat(G)\le 2\cdot\pl(G)-1,$$
$$\frac{\Delta(G)-1}{2}\le  \pat(G)\le 2\cdot\Delta(G)-1,$$
$$\pat(G)\le \pcc(G)\le 2\cdot\pat(G),$$ 
$$\frac{\pl(G)}{2}\leq \pat(G)\le \pcc(G)\le 2\cdot \pl(G).$$  
\end{theorem} 


\begin{proof} Clearly, $\dsp(G)\leq \dpr(G)$ and $\pl(G)\le \Delta(G)$ 
for every graph $G$. The inequality $\pat(G)\le 2\cdot\pl(G)-1$ follows from Proposition \ref{prop:power}. The inequalities 
$\adc(G)\le 2\cdot\pat(G)$, $\Delta(G)\le 2\cdot\pat(G)+1$,  
$\pcc(G)\le 2\cdot \pl(G)$, $\pl(G)\le 2\cdot\pat(G)$,  $\pat(G)\le\pcc(G)\le 3\cdot\adc(G)+2$ and $\adc(G)\le 2\cdot \dsp(G)+2$ are given by Lemma  \ref{lem:pat-length}, Lemma \ref{cpp-pl}, Lemma  \ref{lem:pl-pat}, Lemma \ref{lem:adc-pat} and Lemma \ref{lem:adc-dsp-upperb}, respectively.   
