        \frac{d}{dt}\overline{g}_{p,1}(t) & = \frac{d}{dt} \int_{t}^{L+t} \cos(p f(s,t))\ds \\
    %    & = -p\int_{0}^{L} \sin(p f(s+t,t))(\partial_s f(s+t,t) + \partial_t f(s+t,t))\ds\\
