\subsection{Regular polygons}
We consider the special case that all turning angles of the polygon are equal, i.e., $\alpha_i\equiv\alpha$. We immediately get %$f_1=0,f_{q+1}=2\pi$, and
\begin{align*}
    f_i =\frac{2(i-1)}{q}\pi, \quad i=1,\ldots,q+1.
\end{align*}
This means,
\begin{align*}
    \overline{g}_{p,1}& = \sum_{i=1}^{q}l_i\cos\left(\frac{p}{q}2(i-1)\pi\right), &
    \overline{g}_{p,2}& = \sum_{i=1}^{q}l_i\sin\left(\frac{p}{q}2(i-1)\pi\right).
\end{align*}

In the following theorem we discuss the properties of regular polygons with equal angles and with equal segment lengths. It turns out that these properties lead to extreme eigenvalues of the irreducible surface MT.

\begin{theorem}[Eigenvalue for equal angle polygons]\label{thm:eigenvalues-equal-angle-polygon}
    For an equal angle polygon $\C_q$ with $q$ vertices the normalized eigenvalues $\mu_p$ of the irreducible surface MT $\IF{\W_1^p(\C_q)}$ fulfill
    \[
      \mu_p = \left\{\begin{array}{ll}
          1 & \text{ if }\frac{p}{q} \in\mathbb{N} \\
          0 & \text{ if }\frac{p}{q} \notin\mathbb{N}\text{ and }l_i=\frac{L}{q}.
      \end{array}\right.
    \]
\end{theorem}
\begin{proof}
    For $\frac{p}{q} \in\mathbb{N}$, we can easily see $\overline{g}_{q,1}(t)= L$, $\overline{g}_{q,2}(t)= 0$.
    With $\lambda_0^+ = L$, this implies $\lambda^{+}_q/\lambda_0^+ = 1$.

    If $\frac{p}{q}\notin\mathbb{N}$, then
    \begin{align*}
        \sum_{i=2}^{q}\sin\left(\frac{p}{q}2(i-1)\pi\right) & = \frac{\sin\left(\frac{p(q-1)}{q}\pi\right) \sin\left(p\pi\right) }{\sin\left(\frac{p}{q}\pi\right)} = 0,
    \end{align*}
    and
    \begin{align*}
        1+ \sum_{i=2}^{q}\cos\left(\frac{p}{q}2(i-1)\pi\right)
     %   & =\frac{\sin\left(\frac{p}{q}\pi\right)+\sin\left(\frac{p}{q}\pi +\frac{p(q-1)}{q}2\pi \right) }{2\sin\left(\frac{p}{q}\pi\right)}\\
        & =\frac{\sin\left(p\pi\right)\cos\left(\frac{p(q-1)}{q}\pi \right) }{\sin\left(\frac{p}{q}\pi\right)} = 0.
    \end{align*}
    Thus, for equal angles and equal lengths of the sides, $\lambda^{\pm}_p=0$ if $\frac{p}{q}\notin\mathbb{N}$.
\end{proof}

\begin{remark}
    The assertion of \Cref{thm:eigenvalues-equal-angle-polygon} allows to characterize polygonal shapes on surfaces. This is in analogy to the flat case. However, not all surfaces allow for polygons with equal angles and equal segment lengths. Numerical examples are discussed in \Cref{sec:shape-characterization}.
\end{remark}


\subsection{Stability of surface Minkowski tensors}
As motivated by \cite{SchroderTurk2009Tensorial} in flat space, robustness of the MT against small perturbations is important, see also \cite{Mickel_JCP_2013,happel2025quantifying}. To demonstrate robustness for the surface MT we consider a small deformation of a geodesic polygon $C_q$ by adding an additional vertex $\xb_{k+1/2}$ inside or outside the polygon between the corners $\xb_k=\gamma_k(0)$ and $\xb_{k+1}=\gamma_k(l_k)$. These three points form a geodesic triangle in itself, with turning angles $\beta_i,\;i=1,2,3$ associated to the points $\xb_k,\xb_{k+1/2},\xb_{k+1}$, respectively. Here, we orient the additional triangle in a way, that is consistent with the orientation of $C_q$.
For the enclosed triangular subdomain $\triangle\subset\M$ we set
\begin{align*}
    2\pi \pm \sum_{i=1}^{3}\beta_i=\int_{\triangle}K\dA \equalscolon \kappa_\epsilon,
\end{align*}
where the $\pm$-sign is negative, if the new vertex is outside the polygon, and positive if the new vertex is inside.
Obviously, $ \kappa_\epsilon=0$ if $K\equiv 0$, and $ \kappa_\epsilon \to 0$ if the enclosed area of the triangle goes to 0.
The new vertex $\xb_{k+1/2}$ also defines an extended polygonal curve, denoted by $\tilde{\C}_{q+1}$. For $|\kappa_\epsilon|<\kappa_0$ small enough, the enclosed total Gaussian curvature $\int_{\tilde{\S}_{q+1}} K\dA < 2\pi$.

\begin{lemma}[Continuity of surface Minkowski tensors]\label{lem:continuity}
    Let $\C_q$ be a geodesic polygon and $\tilde{\C}_{q+1}$ a perturbation as above with $|\kappa_\epsilon|<\kappa_0$. The irreducible surface MT $\IF{\W_1^p(\tilde{C}_{q+1})}$ of the perturbed polygon converge to $\IF{\W_1^p(\C_{q})}$ as the perturbation $\kappa_\epsilon$ goes to zero, i.e., $\bar{g}_{p,j}(\tilde{\C}_{q+1}) \to \bar{g}_{p,j}(\C_{q})$ for $\beta_1\to \mp \pi$, $\beta_2\to 0$, and $\beta_3\to \mp \pi$, where the sign is positive, if the new vertex $\xb_{k+1/2}$ is outside $C_q$, and negative if $\xb_{k+1/2}$ is inside.
\end{lemma}
%
\begin{proof}
    With $\sum_{j=1}^{q+1}\tilde{\alpha}_j = \sum_{j=1}^{q}{\alpha}_j \pm \kappa_\epsilon$
    we have
    \begin{align*}
        R_\epsilon &\colonequals \frac{\sum_{j=1}^{q}{\alpha}_j}{\sum_{j=1}^{q+1}\tilde{\alpha}_j} \to 1.
    \end{align*}
    The $\tilde{f}_i$ of the extended polygon $\tilde{\C}_{q+1}$ and the $f_i$ of $\C_q$ fulfill the relations
    \begin{align*}
        \tilde{f}_i & =R_\epsilon f_i, \quad (i=1,\ldots, k-1),\\
        \tilde{f}_k & =R_\epsilon \left( f_k + \frac{2\pi}{\sum_{j=1}^{q}{\alpha}_j} (\beta_1\pm \pi)\right),\\
        \tilde{f}_{k+1} & =R_\epsilon \left( f_k + \frac{2\pi}{\sum_{j=1}^{q}{\alpha}_j} (\beta_1\pm \pi+\beta_2)\right),\\
        \tilde{f}_{i} & =R_\epsilon \left( f_{i-1} \pm \kappa_{\epsilon}  \frac{2\pi}{\sum_{j=1}^{q}{\alpha}_j}\right),\quad (i=k+2,\ldots, q+1).
    \end{align*}
Thus, $\tilde{f}_i$ converges to $f_i$ from which the convergence of the $\bar{g}_{p,j}$ readily follows.
\end{proof}


\section{Convergence properties for discretized curves and surfaces}\label{sec:approximation}
In applications neither the curve $\C$ nor the surface $\M$ might be given exactly. We therefore analyze certain approximation schemes, and provide convergence rates for these. We start by approximating the smooth curve $\C$ by a sequence of geodesic polygons and show that the independent components of the irreducible surface MT converge linearly in the maximal segment length. Next we use an approximation with straight lines in the ambient space $\R^3$ and show the same convergence rate as long as we calculate the angles in the tangent planes to the surface. Lastly,  we show that even a piecewise linear approximation of the surface $\M$ within this scheme still has linear convergence rates.

