\begin{lemma}[Angle approximation]\label{lem:geodesic_angles}
    Let $\gamma:[0,L]\to M$ be of class $C^3$, and let $0=s_1<s_2<\ldots<s_{q+1}=L$ be a partition with $\delta=\max_{i=1,\ldots,q}\delta_i$ small enough. Let $\gamma_q$ be the closed geodesic polygon with corners $\gamma(s_i)$, $i=1,\ldots,q$, and turning angles $\alpha_i$. Then for all $i=1,\ldots, q+1$, we have
        \begin{align*}
            \alpha_i = \frac{1}{2}k_g(s_i)(\delta_{i}+\delta_{i-1}) + O(\max\{|\delta_i|,|\delta_{i-1}|\}^2).
        \end{align*}
\end{lemma}

\begin{proof}
    This is the result of a Taylor expansion of the angle at $s_i$ as a function depending on $s_{i-1}$ and $s_{i+1}$.
\end{proof}

\begin{remark}\label{rem:geodesic_angles}
    If $\C$ is only of class $C^2$, the angles still converge to the curvature, but the convergence order will no longer be quadratic.
    If $\C$ is of class $C^4$ and the partition is equidistant, then
        \begin{align*}
            \alpha_i = \frac{1}{2}k_g(s_i)(\delta_{i}+\delta_{i-1}) + O(\max\{|\delta_i|,|\delta_{i-1}|\}^3)
        \end{align*}
    holds for all $i$.
\end{remark}


\begin{lemma}[Accumulated curvature]\label{lem:geodesic_approx}
    Let $\gamma:[0,L]\to M$ be of class $C^3$, and let $0=s_1<s_2<\ldots<s_{q+1}=L$ be a partition with $\delta=\max_{i=1,\ldots,q}\delta_i$ small enough. Let $\gamma_q$ be the closed geodesic polygon with corners $\gamma(s_i)$, $i=1,\ldots,q$, and turning angles $\alpha_i$. Then there exists a constant $C$ such that for all $i=1,\ldots, q+1$, we have
    \begin{align*}
        \left|\int_{0}^{s_i}k_g(\tau)\dtau - \sum_{j=1}^{i-1}\alpha_j\right| \leq C\delta \left(1+\frac{1}{2}\left(k_g(0)+k_g(s_{i})\right) + L\right).
    \end{align*}
    If additionally $\gamma$ is of class $C^4$ and the partition is equidistant, we obtain for the total curvature
    \begin{align*}
        \left|\int_{\gamma}k_g(\tau)\dtau - \sum_{j=1}^{q}\alpha_j\right| \leq C\delta^2.
    \end{align*}
\end{lemma}
%
\begin{proof}
    The result is stated in \cite[Thm 3.4]{LopezEtAl2010Total} for $\C$ only in $C^2$ for some $\epsilon$ instead of $C\delta$. As the proof is based on the approximation of integrals by a box rule and the local approximation of the angles (see \Cref{lem:geodesic_angles}), the linear order of convergence for curves in $C^3$ can readily be concluded.

    Using an equidistant partition, i.e. $\delta_i=\delta$ for all $i$, and the improved local approximation (see \Cref{rem:geodesic_angles}) for curves in $C^4$ we see that by a midpoint quadrature rule
    \begin{align*}
        \frac{1}{2}k_g(s_i)(\delta_{i}+\delta_{i-1}) =
        \frac{1}{2}\int_{s_{i-1}}^{s_{i+1}}k_g(\tau)\dtau + \frac{1}{6}k_g''(\xi) \delta^3.
    \end{align*}
    Thus, we have
    \begin{align*}
        \alpha_i = \frac{1}{2}\int_{s_{i-1}}^{s_{i+1}}k_g(\tau)\dtau + O(\delta^3).
    \end{align*}
    Summing up, we get for the total curvature (as $q\delta=L$)
    \begin{align*}
        \sum_{i=0}^q \alpha_i &= \int_{\gamma}k_g(\tau)\dtau + O(\delta^2).\qedhere
    \end{align*}
\end{proof}

A direct consequence of this Lemma is that the sum of the angles of the approximating polygon can be arbitrarily close to the total geodesic curvature $\int_\C k_g\ds = 2\pi - \int_\S K \dA$ of $\C$. Thus, the irreducible surface MT are defined for $\C_q$ if $\delta<\delta_0$ small enough depending on $\int_\C k_g\ds$. However, the constants in the approximation error estimate will still depend on the inverse of the total curvature as stated in the following Corollary. In general, approximation results will fail to hold for the limit case.

\begin{corollary}\label{cor:f-fh}
