    \begin{align*}
        |f(s,0) - f_i| & \leq C\delta,
    \end{align*}
    where the constant now additionally depends on the inverse of the total curvature of $\gamma$, the curvature at $s_{i+1}$, and for non-convex curves on the maximum curvature of $\gamma$ at the nodes $s_j$, $j\leq i$.
\end{corollary}
