\title{Heterogeneous Massive MIMO: A Cost-Efficient Technique for Uniform Service in Cellular Networks}

\author{\IEEEauthorblockN{Wei Jiang\IEEEauthorrefmark{1} and Hans Dieter Schotten\IEEEauthorrefmark{2}}
