\noindent To ensure neatness of the presentation, all key results (simple as well as more complicated ones) are formulated as lemmas or theorems.







\vspace{.1in}

\noindent \underline{1) \textbf{\emph{Algebraic phase retrieval characterization:}}}  We start by observing that  rotational invariance of $A$ allows to
 rotate (without loss of generality) $\bar{\x}$ so that it becomes $\bar{\x}=[\|\bar{\x}\|_2,0,\dots,0 ]^T$. One can then
rewrite (\ref{eq:ex1a4a0}) as
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} & & \||A_{:,1}|\|\bar{\x}\|_2-|\z| \|_2^2\nonumber \\
  \mbox{subject to} & &  A\x=\z \nonumber \\
  & & \x^T\bar{\x}=\x_1\|\bar{\x}\|_2= x \nonumber \\
  & & \|\x\|_2^2=c, \label{eq:rdteq0a0}
\end{eqnarray}
where $A_{:,i}$ stands for the $i$-th column of $A$. We al;so find it convenient to set $r\triangleq \sqrt{c-x^2}$. It is then easy to see that restriction to $\|\bar{\x}\|_2=1$ can also be done without loss of generality. One can then rewrite (\ref{eq:rdteq0a0}) as
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} & & \||A_{:,1}|-|\z| \|_2^2\nonumber \\
  \mbox{subject to} & &  A\x=A_{:,1}x + A_{:,2:n}\x_{2:n} = \z \nonumber \\
   & & \sum_{i=2}^{n}\x_i=c-x^2=r^2, \label{eq:rdteq0a1}
\end{eqnarray}
Writing Lagrangian also gives
 \begin{eqnarray}
  \xi(c,x) = \min_{\x,\z} \max_{\y}   & & \||A_{:,1}|-|\z| \|_2^2
  +\y^TA_{:,1}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \nonumber \\
  \mbox{subject to}
     & & \sum_{i=2}^{n}\x_i=c-x^2=r^2. \label{eq:rdteq0a2}
\end{eqnarray}
Setting $\g^{(0)}=A_{:,1}$, one obtains  a more compact form of (\ref{eq:rdteq0a2})
 \begin{eqnarray}
  \xi(c,x) = \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp \||\g^{(0)}|-|\z| \|_2^2
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp. \label{eq:rdteq0a3}
\end{eqnarray}
The above  is a rather useful characterization of the fundamental phase retrieval optimization (f-pro). Together with its implications regarding theoretical solvability of the phase retrieval, it is summarized in the following lemma.

\begin{lemma} Consider real phase retrieval (PR) problem with $n$ unknowns and sample complexity $m$. Let $A\in\mR^{m\times n}$, $\g^{(0)}\triangleq A_{:,1}$, and assume a high-dimensional linear (proportional) regime,
with the over-sampling ratio $\alpha=\lim_{n\rightarrow\infty}\frac{m}{n}$. Then, the PR is theoretically solvable (i.e., it has a unique (up to a global phase) solution) provided that
 \begin{equation}\label{eq:ta10}
 \forall x\neq 1 \qquad f_{rp}(1,x;A)>0,
\end{equation}
where
\begin{equation}\label{eq:ta11}
f_{rp}(c,x;A)\triangleq \frac{1}{n}  \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp \||\g^{(0)}|-|\z| \|_2^2
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp.
\end{equation}
    \label{lemma:lemma1}
\end{lemma}
\begin{proof}
Follows immediately from the above discussion and after recognizing that (\ref{eq:ta11}) is (\ref{eq:rdteq0a3})  cosmetically  scaled by $1/n$.
\end{proof}

The optimization problem on the right hand side of (\ref{eq:ta11}) is the so-called \emph{random primal}. The corresponding \emph{random dual} is determined next.





\vspace{.1in}
\noindent \underline{2) \textbf{\emph{Determining the random dual:}}} As is typical within the RDT, the measure concentration is utilized as well. This practically means that for any fixed $\epsilon >0$,  one has (see, e.g. \cite{StojnicCSetam09,StojnicRegRndDlt10,StojnicICASSP10var})
\begin{equation*}
\lim_{n\rightarrow\infty}\mP_{A}\left (\frac{|f_{rp}(c,x;A)-\mE_{A}(f_{rp}(c,x;A)|}{\mE_{A}(f_{rp}(c,x;A)}>\epsilon\right )\longrightarrow 0.\label{eq:ta15}
\end{equation*}
Another key ingredient of the RDT machinery is the following, so-called random dual, theorem.
\begin{theorem} Assume the setup of Lemma \ref{lemma:lemma1}. Let the elements of $A\in\mR^{m\times n}$ ($\g^{(0)}\in\mR^{m\times 1}$ and $A_{:,2:n}\in\mR^{m\times (n-1)}$), $\g^{(1)}\in\mR^{m\times 1}$, and  $\h^{(1)}\in\mR^{(n-1)\times 1}$  be iid standard normals. Consider two positive scalars $c$ and $x$  ($0\leq x \leq c$) and set $r\triangleq \sqrt{c-x^2}$. Let
\vspace{-.0in}
\begin{eqnarray}
\cG & \triangleq & \lp A,\g^{(1)},\h^{(1)}\rp = \lp\g^{(0)},A_{:,2:n},\g^{(1)},\h^{(1)}\rp  \nonumber \\
\phi(\x,\z,\y) & \triangleq &
 \lp \||\g^{(0)}|-|\z| \|_2^2
  +\y^T \g^{(0)}x   +  \y^T \g^{(1)}\|\x_{2:n}\|_2 + \lp \x_{2:n}  \rp^T\h^{(1)}\|\y\|_2  -\y^T  \z  \rp
\nonumber \\
 f_{rd}(c,x;\cG) & \triangleq &
\frac{1}{n}  \min_{\|\x_{2:n}\|_2=r,\z} \max_{\|\y\|_2=r_y,r_y>0}  \phi(\x,\z,\y)
  \nonumber \\
 \phi_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(c,x;\cG).\label{eq:ta16}
\vspace{-.0in}\end{eqnarray}
One then has \vspace{-.02in}
\begin{eqnarray}
  \lim_{n\rightarrow\infty}\mP_{ A } (f_{rp} (c,x; A )   >  \phi_0)\longrightarrow 1,\label{eq:ta17a0}
\end{eqnarray}
and
\begin{eqnarray}
\hspace{-.3in}(\phi_0  > 0)   &  \Longrightarrow  & \lp \lim_{n\rightarrow\infty}\mP_{\cG}\lp \frac{\xi(c,x)}{n} = f_{rd}(c,x;\cG) >0 \rp \longrightarrow 1\rp
\quad  \Longrightarrow \quad \lp \lim_{n\rightarrow\infty}\mP_{ A } (f_{rp} (c,x; A )   >0)\longrightarrow 1 \rp  \nonumber \\
& \Longrightarrow & \lp \lim_{n\rightarrow\infty}\mP_{A} \lp \mbox{PR is (uniquely) solvable} \rp \longrightarrow 1\rp.\label{eq:ta17}
\end{eqnarray}
 \label{thm:thm1}
\end{theorem}\vspace{-.17in}
\begin{proof}
Follows immediately after conditioning on $\g^{(0)}$ and applying the Gordon's comparison theorem (see, e.g., Theorem B in \cite{Gordon88}). Gordon's theorem is a special case of a series of results Stojnic obtained in \cite{Stojnicgscomp16,Stojnicgscompyx16} (see Theorem 1, Corollary 1, and Section 2.7.2 in \cite{Stojnicgscomp16} as well as Theorem 1, Corollary 1, and Section 2.3.2 in \cite{Stojnicgscompyx16}).
\end{proof}




\vspace{.1in}
\noindent \underline{3) \textbf{\emph{Handling the random dual:}}} We follow the methodologies invented in \cite{StojnicCSetam09,StojnicICASSP10var,StojnicISIT2010binary,StojnicICASSP10block,StojnicRegRndDlt10}. To that end, we first solve the optimizations over $\x$ and $\y$ and obtain from (\ref{eq:ta16})
\begin{equation}
 f_{rd}(c,x;\cG) =
\frac{1}{n}  \min_{\z} \max_{r_y>0}
 \lp \||\g^{(0)}|-|\z| \|_2^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2 r_y - \|\h^{(1)} \|_2 r r_y \rp.
\label{eq:hrd1}
 \end{equation}
We then also have
\begin{eqnarray}
 f_{rd}(c,x;\cG)
  &  =  &
\frac{1}{n}  \min_{\z} \max_{r_y>0}
 \lp \||\g^{(0)}|-|\z| \|_2^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp \nonumber \\
  &  \geq   &
\frac{1}{n}  \max_{r_y>0} \min_{\z}
 \lp \||\g^{(0)}|-|\z| \|_2^2
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp
  \nonumber \\
  &  =   &
\frac{1}{n}  \max_{r_y>0} \min_{\z_i}
 \lp
\sum_{i=1}^{m}
\lp \||\g_i^{(0)}|-|\z_i| \|_2^2
  +\|\g_i^{(0)}x   +  \g_i^{(1)}r -\z_i\|_2^2 r_y \rp
  - \|\h^{(1)} \|_2^2 r^2 r_y \rp
    \nonumber \\
  &  =   &
\frac{1}{n}  \max_{r_y>0} \min_{\z_i}
 \lp
\sum_{i=1}^{m}
\lp \||\g_i^{(0)}|-|\z_i| \|_2^2
  +\||\g_i^{(0)}x   +  \g_i^{(1)}r| -|\z_i|\|_2^2 r_y \rp
  - \|\h^{(1)} \|_2^2 r^2 r_y \rp.
\label{eq:hrd2}
 \end{eqnarray}
Statistical identicalness over $i$ and concentrations then give
\begin{eqnarray}
 \phi_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(\cG)
\geq
  \max_{r_y>0} \mE_{\cG}  \min_{\z_i} \cL_1(r_y),
\label{eq:hrd6}
 \end{eqnarray}
where
\begin{eqnarray}
\cL_1(r_y)
  &  = &
\alpha  \lp \||\g_i^{(0)}|-|\z_i| \|_2^2
  +\||\g_i^{(0)}x   +  \g_i^{(1)}r| -|\z_i|\|_2^2 r_y \rp
  -  r^2 r_y.
\label{eq:hrd7}
 \end{eqnarray}
To optimize over $\z_i$ one first finds the following derivative
\begin{eqnarray}
\frac{d\cL_1(r_y)}{d|\z_i|}
  &  = &
\alpha \lp -2(|\g_i^{(0)}|-|\z_i| )
  -2(|\g_i^{(0)}x   +  \g_i^{(1)}r| -|\z_i|) r_y\rp.
\label{eq:hrd7a0}
 \end{eqnarray}
 Equalling the above derivative to zero allows to determine the optimal $|\z_i|$
\begin{eqnarray}
|\hat{\z}_i|= \frac{1}{1+r_y} \lp |\g_i^{(0)}| + |\g_i^{(0)}x   +  \g_i^{(1)}r| r_y \rp.
\label{eq:hrd7a1}
 \end{eqnarray}
Combining  (\ref{eq:hrd7}) and  (\ref{eq:hrd7a1}) one further obtains
\begin{eqnarray}
\min_{\z_i} \cL_1(r_y)
  &  = &
\alpha  \lp \||\g_i^{(0)}|-|\hat{\z}_i| \|_2^2
  +\||\g_i^{(0)}x   +  \g_i^{(1)}r| -|\hat{\z}_i|\|_2^2 r_y \rp
  -  r^2 r_y \nonumber \\
  &  = &
\alpha
\lp
\frac{r_y^2}{(1+r_y)^2} \lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
  +\frac{1}{(1+r_y)^2} \lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
 r_y \rp
  -  r^2 r_y
  \nonumber \\
    &  = &
\alpha
\frac{r_y}{1+r_y} \lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
  -  r^2 r_y.
\label{eq:hrd7a2}
 \end{eqnarray}
 After setting
\begin{eqnarray}
f_q & \triangleq & \mE_{\cG}\lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2,
\label{eq:hrd7a2a0}
 \end{eqnarray}
 one easily writes
\begin{eqnarray}
 \mE_{\cG} \min_{\z_i} \cL_1(r_y)
     &  = &
\alpha
\frac{r_y}{1+r_y}  \mE_{\cG}\lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
  -  r^2 r_y \nonumber \\
      &  = &
\alpha
\frac{r_y}{1+r_y}  f_q  -  r^2 r_y.
\label{eq:hrd7a3}
 \end{eqnarray}
Plugging this back in (\ref{eq:hrd6}) gives
\begin{eqnarray}
 \phi_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(\cG)
 \nonumber \\
& \geq &
  \max_{r_y>0}
  \lp
  \alpha
\frac{r_y}{1+r_y} \mE_{\cG}\lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
  -  r^2 r_y \rp
  \nonumber \\
  & = &
  \max_{r_y>0}
  \lp
  \alpha
\frac{r_y}{1+r_y} f_q
  -  r^2 r_y \rp.
\label{eq:hrd7a4}
 \end{eqnarray}
It is rather obvious but we point out that inequality signs in (\ref{eq:hrd2}), (\ref{eq:hrd6}), and (\ref{eq:hrd7a4}) can be replaced with equalities. To determine optimal $r_y$ one takes the derivative of the expression under $\max$
\begin{eqnarray}
 \frac{d  \lp
  \alpha
\frac{r_y}{1+r_y} f_q
  -  r^2 r_y \rp}{dr_y} = \alpha\frac{1}{\lp1+r_y\rp^2}f_q -r^2.
\label{eq:hrd7a5}
 \end{eqnarray}
Equalling the above derivative to zero gives for the optimal $r_y$
\begin{eqnarray}
\hat{r}_y
  = \max\lp \frac{\sqrt{ \alpha f_q}}{r} -1,0\rp.
\label{eq:hrd7a6}
 \end{eqnarray}
Combining (\ref{eq:hrd7a4}) and (\ref{eq:hrd7a6}) one finally finds
\begin{eqnarray}
 \phi_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f_{rd}(\cG)
  \geq
\max\lp \sqrt{\alpha f_q}
  -  r,0\rp^2.
\label{eq:hrd7a7}
 \end{eqnarray}
After setting
\begin{eqnarray}
A & = &  g_1^2\sqrt{c-r^2} \nonumber \\
B & = & g_1r \nonumber \\
C & = & -g_1\frac{\sqrt{c-r^2}}{r} \nonumber \\
I_1 & = & \frac{A}{2} \erfc\lp \frac{C}{\sqrt{2}}\rp   + B \frac{e^{-\frac{C^2}{2}}}{\sqrt{2\pi}} \nonumber \\
I_2 & = & -A \lp  1-\frac{1}{2}\erfc \lp  \frac{C}{\sqrt{2}}  \rp  \rp + B \frac{e^{-\frac{C^2}{2}}}{\sqrt{2\pi}} \nonumber \\
I & = & I_1+I_2,
\label{eq:hrd7a8}
\end{eqnarray}
 and solving the remaining integrals one also obtains
\begin{eqnarray}
f_{g,1} & = &  (1+c) - 2I \nonumber \\
f_q & \triangleq & \mE_{\cG}\lp |\g_i^{(0)}| - |\g_i^{(0)}x   +  \g_i^{(1)}r|  \rp^2
 =  \frac{2}{\sqrt{2\pi}} \int_{0}^{\infty}f_{q,1}e^{-\frac{g_1^2}{2}}dg_1.
 \label{eq:hrd7a9}
\end{eqnarray}





  \vspace{.1in}
\noindent \underline{4) \textbf{\emph{Double checking the strong random duality:}}}  Double checking for the strong random duality is the last step of the RDT machinery. However, since a deterministic strong duality is not present the reversal considerations from \cite{StojnicRegRndDlt10}  and the strong random duality are not in place. This basically implies that the above mechanism produces strict lower bounds on the f-pro's scaled objective, $\xi(c,x)$ .










